const top_xinzhao = {
  champion: '신짜오',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '1~2레벨 구간에는 (Q)\'삼조격\'으로 가렌을 공중에 띄우며 짧게 딜교환을 하고 빠지세요. 가렌은 (P)\'인내심\'으로 체력을 회복하니 미니언을 치면서 체력을 계속 깎아 두는 것이 좋아요. (Q)\'결정타\'는 걸려 있는 둔화를 제거하고 이동 속도를 올려 주니 (W)\'풍전참뢰\'의 둔화에만 기대지 말고 (Q)\'결정타\'가 빠진 뒤에 붙으세요.', lv3: '가렌이 (Q)\'결정타\'를 사용해 침묵을 걸며 달려든다면 (E)\'무쌍돌격\'으로 빠르게 거리를 좁히고 (Q)\'삼조격\'으로 적을 띄우는 것을 노려보세요. 가렌이 (W)\'용기\'를 켜서 보호막을 얻었을 때는 딜을 아끼고 가렌의 스킬이 빠진 뒤에 다시 붙는 것이 좋아요. (E)\'심판\'의 회전 피해를 피하면서 (W)\'풍전참뢰\'의 둔화와 (E)\'무쌍돌격\'의 공격 속도 증가를 활용해 몰아붙이세요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 잃은 체력이 많을수록 피해가 커지니 체력이 낮을 때는 무리하게 붙지 마세요. 가렌은 근접 챔피언이라 창이 닿는 거리 안에서는 (R)\'현월수호\'로도 피해를 받으니, (E)\'심판\'과 (Q)\'결정타\'가 빠진 뒤에 (R)\'현월수호\'로 밀쳐내고 (Q)\'삼조격\'으로 역습하세요. 정글러가 개입할 때는 (R)\'현월수호\'로 도전 받지 않은 적을 밀쳐내 진형을 흐트러뜨리고 빠지세요.', item: '첫 코어로 갈라진 하늘을 가면 체력과 첫 타격의 회복으로 교전을 버티기 좋아요. 신발은 가렌의 기본 공격 피해를 줄여 주는 판금 장화를 선택하세요.', spell: '점멸과 점화를 추천해요. 점화로 가렌의 (P)\'인내심\' 회복 효과를 낮춰주면 전투에서 승리하기 훨씬 수월해요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 멀리서 견제하며 골드를 챙겨요. 이 스킬은 대상을 직접 지정하니 미니언 사이에 섞여도 피할 수 없으므로 견제를 받는 동안 체력을 관리하세요. 갱플랭크가 미니언을 치러 올 때 (Q)\'삼조격\'으로 짧게 딜교환하고, 근접 평타에 (P)\'불의 심판\'이 붙으니 오래 머무르지 마세요.', lv3: '갱플랭크가 (E)\'화약통\'을 깔아두면 폭발 범위에 들어가지 않도록 주의하며 싸우세요. (W)\'괴혈병 치료\'는 모든 방해 효과를 제거하고 체력을 회복하니, 이 스킬이 빠진 뒤에 (W)\'풍전참뢰\'로 둔화를 걸고 붙으세요. (E)\'무쌍돌격\'으로 접근해 (Q)\'삼조격\'의 공중 띄우기까지 연계하면 딜교환을 이끌 수 있어요.', lv6: '갱플랭크의 (R)\'포탄 세례\'가 깔린 지역은 둔화가 걸리니 무리하게 진입하지 마세요. 갱플랭크가 (W)\'괴혈병 치료\'를 사용하지 못했을 때 (R)\'현월수호\'를 사용하여 적의 공격을 피하며 진입하면 킬각을 잡을 수 있어요. 라인을 밀어넣어 갱플랭크가 (Q)\'혀어어어업상\'으로 골드를 수급하기 어렵게 압박하세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 갱플랭크의 기본 공격 피해를 줄여주며, 갈라진 하늘은 전투 지속력을 높여줘요.', spell: '점멸과 점화를 추천해요. 점화로 갱플랭크의 (W)\'괴혈병 치료\' 회복량을 줄이면 전투에서 훨씬 앞서가요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화를 걸며 견제하고 (P)\'서비스 시간\'으로 체력을 회복해요. (Q)\'삼조격\'의 마지막 공격이 핵심이니 술통을 피하며 거리를 좁히고 딜교환을 하세요. 1~2레벨에는 무리하게 들어가기보다 술통의 위치를 확인하며 파밍에 집중하세요.', lv3: '그라가스의 (E)\'몸통 박치기\'는 공중으로 띄우니 이 스킬을 맞지 않도록 주의하며 (E)\'무쌍돌격\'으로 거리를 좁히세요. 그라가스가 (W)\'취중 분노\'를 사용하면 받는 피해가 줄어드니 스킬을 아끼다가 효과가 끝난 뒤에 (Q)\'삼조격\'으로 몰아치세요. (W)\'풍전참뢰\'를 먼저 맞혀 도전 받은 상태로 만들면 (E)\'무쌍돌격\'의 사거리가 늘어나 붙기가 훨씬 쉬워져요.', lv6: '그라가스의 (R)\'술통 폭발\'은 맞으면 멀리 밀려나니 궁극기가 빠질 때까지 위치를 신경 쓰며 싸우세요. 궁극기가 빠진 뒤에 (E)\'무쌍돌격\'으로 진입해 (Q)\'삼조격\'을 맞히고 (R)\'현월수호\'로 마무리하며 킬을 노려보세요. (E)\'몸통 박치기\' 연계가 무서우니 정글러의 위치를 확인하며 라인을 관리하세요.', item: '첫 코어로 갈라진 하늘을 가서 교전에서 버티세요. 신발은 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 그라가스의 (P)\'서비스 시간\' 회복을 억제하여 킬각을 잡기 편해요.' },
    '그웬': { lv1: '그웬은 (P)\'가위 난도질\' 패시브의 회복 효과 덕분에 전투가 길어질수록 강해져요. 1~2레벨에는 (Q)\'삼조격\'의 에어본을 활용해 짧게 때리고 바로 빠지는 것이 좋아요. 무리하게 평타를 계속 치면 그웬의 회복량에 밀릴 수 있으니 주의하세요.', lv3: '그웬이 (W)\'신성한 안개\'를 사용하면 안개 밖의 신짜오는 그웬을 대상으로 지정할 수 없어요. (W)\'신성한 안개\'가 유지되는 동안은 무리하게 들어가기보다 (E)\'무쌍돌격\'을 아껴두며 타이밍을 보세요. 그웬의 (Q)\'싹둑싹둑!\' 원뿔 범위를 피하며 (W)\'풍전참뢰\'를 맞혀 둔화를 거는 것이 중요해요.', lv6: '그웬의 (R)\'바느질\'은 멀리서 던지는 바늘이라 그웬이 창 거리 밖에 있을 때 (R)\'현월수호\'를 켜 두면 그 피해를 받지 않아요. 그웬이 (E)\'돌격가위\'로 들어오면 (Q)\'삼조격\'의 띄우기와 (W)\'풍전참뢰\'로 반격하고, (W)\'신성한 안개\' 안에서는 걸어 들어가 평타로 싸우세요. 그웬이 안개로 버티기 전에 정글러와 함께 빠르게 싸움을 마무리하세요.', item: '그웬의 마법 피해를 줄여주는 헤르메스의 발걸음과 전투 지속력을 위해 갈라진 하늘을 가세요. 그웬의 주력 피해가 마법 피해이기에 효율적이에요.', spell: '점멸과 점화를 추천해요. 점화로 그웬의 (P)\'가위 난도질\' 회복 효과를 줄여야 전투에서 이길 수 있어요.' },
    '나르': { lv1: '나르는 (Q)\'부메랑 던지기\'로 둔화를 걸며 견제하려 해요. 부메랑의 궤적에서 비켜나며 피해를 최소화하고, 나르가 평타를 치러 다가올 때 (Q)\'삼조격\'으로 빠르게 세 번째 공격까지 적중시켜 띄우세요. (E)\'폴짝\'으로 빠지는 나르를 무리하게 쫓기보다 (P)\'결심\'의 회복으로 체력을 관리하며 기회를 보세요.', lv3: '(W)\'풍전참뢰\'로 먼저 둔화를 걸고 (E)\'무쌍돌격\'으로 빠르게 진입해 딜교환을 하세요. 작은 나르일 때 (Q)\'삼조격\'을 끝까지 적중시켜 공중으로 띄우며 짧게 끝내세요. 분노가 쌓여 메가 나르로 변신하면 (W)\'쿵쾅\' 기절에 맞지 않도록 정면에서 거리를 두세요.', lv6: '메가 나르의 (R)\'나르!\'에 밀려 벽에 부딪히면 기절하므로 벽 근처에서 싸우지 마세요. 작은 나르 상태일 때 (E)\'무쌍돌격\'으로 들어가 (R)\'현월수호\'를 사용해 큰 피해를 입히고 빠르게 정리하세요. 나르의 변신 주기와 쿨타임을 확인하며 정글러와 함께 덮치는 것이 좋아요.', item: '갈라진 하늘로 체력을 보충하고 첫 타격의 피해와 회복을 챙기세요. 신발은 나르의 기본 공격 피해를 줄여주는 판금 장화가 어울려요.', spell: '점멸과 점화를 추천해요. 작은 나르일 때 딜교환 후 점화로 확실하게 킬각을 잡을 수 있어요.' },
    '나서스': { lv1: '나서스는 (Q)\'흡수의 일격\'으로 미니언을 먹으며 성장하려고 해요. (Q)\'삼조격\'의 세 번째 공격 에어본과 (P)\'결심\'의 회복을 활용해 초반에 적극적으로 압박하세요. 나서스가 미니언을 챙기려 할 때 (E)\'무쌍돌격\'으로 들어가 짧게 교환하는 것이 좋아요.', lv3: '나서스의 (W)\'쇠약\'에 걸리면 이동 속도와 공격 속도가 줄어들어 대응하기 어려워져요. (E)\'무쌍돌격\'으로 진입하기 전에 (W)\'풍전참뢰\'를 먼저 맞춰서 둔화를 건 뒤에 들어가는 것이 효과적이에요. 나서스가 (E)\'영혼의 불길\'을 사용하면 방어력이 낮아지니 그 구역 안에서는 싸움을 피하세요.', lv6: '나서스가 (R)\'사막의 분노\'를 사용하면 체력과 공격 범위가 늘어나니 주의해야 해요. 나서스는 근접이라 붙어 있으면 (R)\'현월수호\'로도 피해를 받으니, (R)\'현월수호\'로 밀어낸 뒤 거리를 벌려 폭풍 지속시간이 끝나길 기다리세요. 나서스가 미니언을 먹지 못하도록 라인을 계속 밀어 넣고 정글러를 불러 압박하세요.', item: '갈라진 하늘을 첫 코어로 올려 전투 지속력을 높이세요. 신발은 나서스의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 나서스의 (P)\'영혼의 포식자\'를 통한 체력 회복을 억제하고 킬을 노리세요.' },
    '녹턴': { lv1: '녹턴의 (Q)\'황혼의 인도자\'가 남기는 궤적을 조심하며 거리를 조절하세요. (Q)\'삼조격\'의 세 번째 공격을 준비하며 (P)\'결심\' 패시브로 체력을 관리해요. 초반에는 무리하게 진입하기보다 미니언을 안전하게 챙겨요.', lv3: '녹턴이 (W)\'어둠의 장막\'을 사용해 스킬을 막을 수 있으니 주의해야 해요. (W)\'풍전참뢰\'로 둔화를 건 뒤 (E)\'무쌍돌격\'으로 빠르게 접근하세요. (Q)\'삼조격\'의 에어본을 맞히면 교전에서 앞서갈 수 있어요.', lv6: '녹턴이 (R)\'피해망상\'으로 돌격해 붙으면 이미 창이 닿는 거리 안이니 (R)\'현월수호\'의 보호를 기대하지 말고 돌격 직후 밀쳐내 거리를 벌리세요. (E)\'말할 수 없는 공포\'는 연결이 끊어지지 않으면 공포에 빠지니 연결 거리를 벗어나는 것이 중요해요. 궁극기 사용 후에는 라인 상황을 살피며 정글러의 개입을 기다려요.', item: '판금 장화와 갈라진 하늘을 가요. 녹턴의 기본 공격 피해를 줄이고 공격력을 높이기 위해서예요.', spell: '점멸과 점화를 추천해요. 점화로 녹턴의 (P)\'그림자 칼날\' 회복을 줄이고 마무리 피해를 더해 킬을 노려요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\'이 쌓일수록 강해지니 1~2레벨에는 무리하게 맞딜하지 마세요. (Q)\'학살\'의 도끼날에 맞으면 피해가 크고 체력이 회복되니 도끼자루 부분에 맞도록 거리를 조절하며 (Q)\'삼조격\'으로 짧게 교환하세요.', lv3: '다리우스의 (E)\'포획\'은 끌어당기며 공중으로 띄우니 맞으면 스킬을 쓸 수 없어요. (E)\'포획\'이 빠진 것을 확인한 뒤에 (E)\'무쌍돌격\'으로 거리를 좁히고 (Q)\'삼조격\'으로 띄워 (P)\'결심\' 효과로 체력을 회복하며 교환하세요. 먼저 (W)\'풍전참뢰\'로 견제해 (E)\'포획\'을 쓰게 만드는 것도 방법이에요.', lv6: '다리우스의 (R)\'녹서스의 단두대\'는 중첩된 (P)\'과다출혈\' 때문에 피해가 매우 크니 체력이 낮을 때는 싸움을 피하세요. 다리우스가 붙어 압박할 때 (R)\'현월수호\'로 밀쳐내 거리를 벌리고 (Q)\'삼조격\'으로 역습하세요. (R)\'현월수호\'는 창이 닿는 거리 안의 공격은 막지 못하니 붙은 상태로 버티지 마세요.', item: '첫 코어로 갈라진 하늘을 선택해 전투 중 체력을 보충하고 폭발적인 피해를 입히세요. 신발은 다리우스의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 탈진을 추천해요. 다리우스가 (E)\'포획\'으로 끌어당겨 몰아칠 때 탈진을 사용하여 피해량을 줄이며 버티세요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 일직선으로 발사하며 견제하므로 미니언 뒤에 서서 피해를 피하세요. 1~2레벨에는 라이즈의 사거리가 길어 압박을 받을 수 있으니 (Q)\'삼조격\'의 세 번째 공격을 맞히기 위해 신중하게 접근해야 해요.', lv3: '라이즈가 (E)\'주문 전이\'를 맞힌 후 (W)\'룬 감옥\'을 사용하면 속박이 걸리니 표식이 남은 상태에서는 조심하세요. (W)\'룬 감옥\'은 대상 지정 스킬이라 피할 수 없으니, 라이즈가 이 스킬을 쓴 뒤 (W)\'풍전참뢰\'로 둔화를 걸고 (E)\'무쌍돌격\'으로 빠르게 진입해 (Q)\'삼조격\'의 에어본을 노리세요.', lv6: '라이즈는 (R)\'공간 왜곡\'으로 차원문 근처 아군과 함께 다른 위치로 순간이동할 수 있으니 차원문이 보이면 무리하게 진입하지 마세요. 딜교환할 때 (R)\'현월수호\'를 켜면 창 거리 밖에서 날아오는 라이즈의 스킬 피해를 받지 않으니 이때 (Q)\'삼조격\'으로 킬각을 잡으세요.', item: '헤르메스의 발걸음을 구매해 마법 저항력을 확보하고 마법 피해를 줄이세요. 첫 코어 아이템은 갈라진 하늘을 선택해 체력을 늘리고 교전 능력을 높이세요.', spell: '점멸과 점화를 추천해요. 라이즈가 거리를 벌리더라도 점멸로 접근하고 점화로 마무리하세요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'를 사용하며 근접 거리에서 강력하게 압박해요. (E)\'전기 작살\'로 둔화를 묻히며 마법 저항력을 깎을 수 있으니 (Q)\'삼조격\'을 준비하며 거리를 조절하세요. 상대의 열기가 쌓여 위험 상태가 되기 전까지는 무리한 진입을 피해야 해요.', lv3: '럼블이 (W)\'고철 방패\'를 사용하여 피해를 흡수할 때는 (Q)\'삼조격\'으로 무리하게 딜교하지 마세요. 럼블의 열기가 낮을 때 (E)\'무쌍돌격\'으로 진입하여 (W)\'풍전참뢰\'의 둔화를 맞히며 (P)\'결심\'의 회복을 활용해 싸우세요. (E)\'전기 작살\'의 둔화에 걸리면 뒤로 물러나며 열기가 과열될 때까지 기다려야 해요.', lv6: '럼블이 (R)\'이퀄라이저 미사일\'을 깔면 불타는 궤적이 둔화와 지속 피해를 주니 그 위에서 싸우지 말고 빠르게 벗어나세요. 럼블이 과열되어 스킬을 못 쓰는 타이밍에 (E)\'무쌍돌격\'과 (Q)\'삼조격\'을 연계하고 (R)\'현월수호\'로 마무리하면 킬을 노릴 수 있어요. 라인을 밀어 넣을 때는 럼블의 궁극기 사거리가 길다는 점을 고려해 정글러의 위치를 꼭 확인하세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 가세요. 럼블의 마법 피해를 줄이고 첫 타격의 강한 피해로 교전을 이끌기 위해서예요.', spell: '점멸과 점화를 추천해요. 럼블이 (W)\'고철 방패\'로 버티더라도 점화의 고정 피해로 킬각을 확실히 잡을 수 있어요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 피해를 주고 체력을 회복하며 초반 교전에 강해요. (Q)\'삼조격\'의 세 번째 공격으로 상대를 공중으로 띄워 흐름을 끊어내세요. 무리하게 붙기보다 기본 공격으로 체력 회복 패시브 (P)\'결심\'을 챙기며 거리를 조절하세요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 진입해 (W)\'무자비한 포식자\' 기절을 노리니 주의하세요. 먼저 (W)\'풍전참뢰\'로 적을 둔화시키고 도전 상태로 만든 뒤 (E)\'무쌍돌격\'으로 빠르게 진입해 공격 속도를 높이세요. (W)\'무자비한 포식자\' 기절에 걸리면 스킬을 쓸 수 없으니 레넥톤의 분노가 높을 때는 정면 승부를 피하세요.', lv6: '(R)\'강신\'을 사용한 레넥톤은 추가 체력이 늘고 분노가 빠르게 차니 지속시간이 끝날 때까지 기다리세요. (R)\'현월수호\'를 사용해 주변 적에게 피해를 입히고 도전 받지 않은 레넥톤을 뒤로 밀어내며 거리를 확보하세요. 레넥톤은 근접이라 붙어 있으면 (R)\'현월수호\'로도 피해를 받으니 밀어낸 뒤 정글러의 개입을 기다리세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력을 보강하고 타격 시 체력을 회복하며 유지력을 높이세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 점화로 레넥톤의 (Q)\'양떼 도륙\' 회복량을 줄여야 교전에서 앞설 수 있어요.' },
    '렝가': { lv1: '렝가가 수풀에서 (P)\'보이지 않는 포식자\'로 도약하며 기습하는 것을 경계하며 거리를 조절하세요. (Q)\'삼조격\'을 활용해 적을 견제하며 안정적으로 라인을 유지해요.', lv3: '렝가의 (E)\'올가미 투척\'은 처음 맞은 적을 둔화시키고 야성이 최대일 때는 속박하니 미니언 뒤에 서서 피하세요. 올가미가 빠지면 (W)\'풍전참뢰\'로 둔화를 건 뒤 (E)\'무쌍돌격\'으로 접근해 (Q)\'삼조격\'의 마지막 공격으로 공중에 띄우세요.', lv6: '렝가가 (R)\'사냥의 전율\'로 도약해 들어올 때 (R)\'현월수호\'를 사용해 주변 적을 밀쳐내며 대응하세요. 렝가는 근접이라 붙은 상태에서는 (R)\'현월수호\'가 피해를 막아 주지 못하니 밀쳐낸 뒤 (Q)\'삼조격\'으로 역습하며 라인을 압박해요.', item: '판금 장화와 갈라진 하늘을 가세요. 판금 장화는 기본 공격으로 받는 피해를 줄여주고 갈라진 하늘은 체력과 공격력을 제공해요.', spell: '점멸과 점화를 사용하세요. 점화는 렝가의 (W)\'전투의 포효\'를 통한 체력 회복을 감소시켜 킬을 노리기 수월해요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'를 활용한 돌진과 (P)\'룬 검\' 추가 피해로 초반 교환이 강해요. 1~2레벨에는 무리하게 맞붙지 말고 (Q)\'삼조격\'을 활용해 미니언과 함께 딜교환하며 체력을 관리하세요. 리븐이 돌진할 때 (W)\'풍전참뢰\'를 맞춰 둔화를 걸면 거리를 조절하기 쉬워요.', lv3: '(W)\'기 폭발\' 기절을 맞으면 위험하니 리븐의 스킬이 빠지는 것을 확인하고 (E)\'무쌍돌격\'으로 진입하세요. 리븐이 (E)\'용맹\'으로 피해를 흡수할 때는 (Q)\'삼조격\'의 마지막 타격을 맞춰 공중으로 띄우는 데 집중하세요. (W)\'풍전참뢰\'를 먼저 맞히면 (E)\'무쌍돌격\'의 사거리가 늘어나 리븐에게 더 쉽게 접근할 수 있어요.', lv6: '리븐이 (R)\'추방자의 검\'을 사용하여 공격 사거리가 늘어난 상태라면 (R)\'현월수호\'로 리븐의 공격 범위를 벗어나 피해를 받지 않는 상태를 만드세요. 리븐의 스킬 연계를 (R)\'현월수호\'로 대응하며 거리 밖으로 밀어내 피해를 최소화하세요. 정글러와 협력해 리븐이 (E)\'용맹\'으로 버티기 전에 빠르게 정리하는 것이 좋아요.', item: '첫 코어 아이템으로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 리븐의 물리 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 마무리 피해를 더해 킬을 가져오세요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'이 미니언을 꿰뚫고 지나가므로 미니언 뒤에 숨어도 피해를 입으니 주의하세요. 1~2레벨에는 리산드라의 견제를 피하며 (Q)\'삼조격\'을 활용해 짧은 딜교환을 시도하세요. 거리 조절을 통해 리산드라의 스킬을 맞지 않도록 행동하는 것이 좋아요.', lv3: '리산드라가 (W)\'서릿발\'로 발을 묶기 전에 (W)\'풍전참뢰\'를 맞혀 도전 상태로 만드는 것이 중요해요. 도전 상태가 되면 (E)\'무쌍돌격\'의 사거리가 늘어나 리산드라에게 더 쉽게 접근할 수 있어요. 리산드라가 (E)\'얼음갈퀴 길\'로 거리를 벌리려 하면 (E)\'무쌍돌격\'으로 빠르게 쫓아가세요.', lv6: '리산드라의 (R)\'얼음 무덤\' 기절은 (R)\'현월수호\'로 막을 수 없으니 궁극기가 빠진 것을 확인한 뒤에 진입하세요. 리산드라가 자신에게 (R)\'얼음 무덤\'을 써서 무적이 되면 공격을 멈추고 효과가 끝나기를 기다려야 해요. 그 뒤 (Q)\'삼조격\'의 세 번째 공격으로 상대를 띄우며 킬각을 노려보세요.', item: '첫 코어 아이템으로 갈라진 하늘을 선택해 체력과 공격력을 챙기세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 신어주세요.', spell: '점멸과 정화를 추천해요. (R)\'얼음 무덤\' 기절과 (W)\'서릿발\' 속박은 모두 정화로 풀 수 있어요. 점멸은 거리를 좁히거나 스킬을 피해 빠질 때 쓰세요.' },
    '마스터이': { lv1: '1~2레벨에는 (Q)\'삼조격\'의 마지막 공격으로 상대를 공중으로 띄우며 딜교환을 시작하세요. 마스터 이의 평타가 강하니 (E)\'무쌍돌격\'을 사용하여 적절한 거리에서 싸우며 체력을 보존하세요. 상대가 (Q)\'일격 필살\'을 써서 대상으로 지정할 수 없게 되면 무리하게 스킬을 쓰지 마세요.', lv3: '(W)\'풍전참뢰\'를 맞혀 마스터 이를 둔화시킨 뒤 (E)\'무쌍돌격\'으로 진입해 (Q)\'삼조격\'의 마지막 공격을 맞히는 것이 중요해요. 마스터 이가 (W)\'명상\'을 사용해 받는 피해량을 줄이며 체력을 회복한다면 무리하게 싸우지 말고 빠져나오세요. 상대의 (Q)\'일격 필살\'이 빠진 상태에서 딜교를 해야 해요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 켜면 둔화에 면역이라 (W)\'풍전참뢰\'와 (E)\'무쌍돌격\'의 둔화는 통하지 않지만 (Q)\'삼조격\'의 띄우기는 통해요. (Q)\'일격 필살\'이 끝나 다시 대상으로 지정할 수 있게 되면 (Q)\'삼조격\'으로 띄우고 (R)\'현월수호\'로 피해를 더해 맞서세요. 마스터 이가 킬을 먹어 스킬 재사용 대기시간이 줄어들지 않도록 정글러를 불러 함께 압박하세요.', item: '첫 코어로 갈라진 하늘을 가서 전투 지속력을 높이세요. 신발은 마스터 이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 마스터 이의 (W)\'명상\' 체력 회복 효과를 줄여야 해요.' },
    '마오카이': { lv1: '마오카이는 (Q)\'덤불 주먹\'으로 적을 밀어내며 둔화를 걸고 (P)\'마법 흡수\'로 체력을 회복해요. (Q)\'삼조격\'을 사용하여 상대를 공중으로 띄우며 딜교환을 시도하고, 마오카이가 (Q)\'덤불 주먹\'을 쓰려 할 때 거리를 조절하세요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 돌진해 속박을 시도하면 (E)\'무쌍돌격\'으로 거리를 좁혀 대응하세요. (W)\'풍전참뢰\'를 먼저 맞춰 도전 상태로 만든 뒤 (E)\'무쌍돌격\'을 사용하면 더 멀리서 빠르게 붙을 수 있어요. (E)\'묘목 던지기\'가 깔린 수풀 근처는 피하며 싸우세요.', lv6: '마오카이의 (R)\'대자연의 마수\' 벽이 다가오면 벽에 닿아 속박되지 않도록 옆으로 피하며 싸우세요. (R)\'현월수호\'를 사용하여 마오카이의 공격 범위를 차단하고 진형을 붕괴시키면 적을 처치하기 좋아요. 마오카이가 궁극기를 사용하면 라인을 밀어두고 정글러의 합류를 준비하세요.', item: '마법 피해를 입히는 마오카이를 상대하므로 헤르메스의 발걸음을 선택하세요. 첫 코어 아이템으로는 전투 지속력을 높여주는 갈라진 하늘을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 마오카이의 (P)\'마법 흡수\' 회복을 줄이고 마무리 피해를 더해 킬을 노리기 좋아요.' },
    '말자하': { lv1: '말자하의 (P)\'공허 태세\'는 피해를 입으면 잠시 후 사라지니 (Q)\'삼조격\'이나 평타를 먼저 맞춰 받는 피해 감소와 군중 제어 면역을 풀어야 해요. (Q)\'공허의 부름\'은 침묵을 걸어 스킬 사용을 막으니 문이 열리는 위치를 피해 움직이며 거리를 조절하세요. 1~2레벨에는 근접 전투에서 신 짜오가 앞서나가기 쉬우니 적극적으로 압박해요.', lv3: '말자하의 (Q)\'공허의 부름\'이 빠진 것을 확인한 뒤에 (E)\'무쌍돌격\'으로 빠르게 접근해야 해요. (E)\'재앙의 환상\'에 걸리면 (W)\'공허의 무리\' 공허충과 함께 지속적인 피해를 입으니 (W)\'풍전참뢰\'로 둔화를 걸고 빠르게 딜교환을 마쳐요. 말자하의 스킬을 피하며 (Q)\'삼조격\'의 에어본을 맞히는 것이 중요해요.', lv6: '말자하의 (R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없고 제압 중에는 스킬도 쓸 수 없으니, 궁극기가 빠진 타이밍에 (E)\'무쌍돌격\'으로 진입해 킬각을 잡으세요. 진입한 뒤에는 (R)\'현월수호\'를 켜서 창 거리 밖에서 들어오는 공격의 피해를 받지 않는 상태로 싸우세요. 라인을 빠르게 밀어 넣고 정글러를 불러서 말자하를 압박하는 것이 좋아요.', item: '첫 코어 아이템으로는 갈라진 하늘을 가세요. 신발은 마법 피해와 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (R)\'황천의 손아귀\' 제압은 정화로 풀 수 없으니 제압이 걸리기 전에 위치를 잡고, 점화는 마무리 피해에 쓰세요.' },
    '말파이트': { lv1: '말파이트는 (P)\'화강암 방패\'로 피해를 흡수하며 (Q)\'지진의 파편\'으로 견제해요. (Q)\'지진의 파편\'은 대상을 직접 지정하니 걸어서 피할 수 없고 둔화가 따라오므로 맞은 뒤에는 무리하게 싸우지 마세요. 방패가 재생성되기 전에 (Q)\'삼조격\'으로 짧게 딜교환을 시도하는 것이 좋아요.', lv3: '말파이트의 (E)\'지면 강타\'를 맞으면 공격 속도가 감소하니 주의하세요. (E)\'무쌍돌격\'으로 접근할 때 말파이트의 (W)\'천둥소리\' 여진이 발생하기 전에 (W)\'풍전참뢰\'로 먼저 둔화를 거는 것이 좋아요. (Q)\'삼조격\'의 에어본을 맞히면 더 강한 압박이 가능해요.', lv6: '말파이트의 (R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 막을 수 없고, 맞으면 에어본 상태가 되어 스킬을 쓸 수 없어요. 에어본이 끝난 뒤 (R)\'현월수호\'로 주변 적에게 피해를 주고 (Q)\'삼조격\'으로 반격하세요. 정글러와 함께 말파이트의 궁극기가 빠진 타이밍에 압박하는 것도 좋아요.', item: '첫 코어로 갈라진 하늘을 선택해 체력과 공격력을 동시에 챙기세요. 신발은 말파이트의 마법 피해를 줄이고 강인함을 얻을 수 있는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 말파이트의 체력을 깎아 킬각을 잡기에 좋아요.' },
    '모데카이저': { lv1: '1~2레벨에는 (Q)\'삼조격\'의 세 번째 공격으로 상대를 공중에 띄워 딜교환을 시작하세요. 모데카이저의 (Q)\'말살\'은 혼자 맞을 때 피해가 커지니 혼자 서 있지 말고 미니언 근처에서 거리를 조절해요.', lv3: '(E)\'무쌍돌격\'으로 빠르게 접근해 모데카이저의 (E)\'죽음의 손아귀\'가 빠진 틈을 노려 딜교환을 하세요. (W)\'풍전참뢰\'를 적중시켜 둔화를 걸면 (Q)\'삼조격\'을 통한 추격과 딜교가 훨씬 수월해져요.', lv6: '모데카이저가 (R)\'죽음의 세계\'를 사용하면 능력치를 뺏기고 그 안에서는 순간이동이나 궁극기로 빠져나갈 수 없으니 궁극기를 맞기 전에 체력을 관리하세요. (E)\'죽음의 손아귀\'에 끌려가기 전에 (E)\'무쌍돌격\'으로 거리를 조절하세요. 끌려갔다면 (R)\'현월수호\'로 밀쳐내며 반격하세요.', item: '첫 코어 아이템은 갈라진 하늘을 선택해 전투 지속력을 높여요. 신발은 모데카이저의 마법 피해를 견디기 위해 헤르메스의 발걸음을 신어주세요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'불멸\'의 체력 회복 전에 마무리 피해를 더해 킬각을 만드세요.' },
    '문도박사': { lv1: '1~2레벨에는 (Q)\'삼조격\'의 세 번째 공격으로 에어본을 노리며 압박하세요. 문도박사가 (Q)\'오염된 뼈톱\'을 던질 때는 미니언 뒤에 숨어 투사체를 피하는 것이 좋아요. 문도가 통을 주워 체력을 회복하기 전에 (W)\'풍전참뢰\'로 둔화를 걸며 거리 조절을 하세요.', lv3: '3레벨 이후에는 (W)\'풍전참뢰\'를 먼저 맞춰 문도를 도전 상태로 만든 뒤 (E)\'무쌍돌격\'으로 진입하세요. 문도가 (W)\'심장 전기 충격\'을 켜고 피해를 저장하면 맞교환을 피하고 (Q)\'삼조격\'으로 짧게 딜교환을 해요. 문도가 (Q)\'오염된 뼈톱\'을 던지는 타이밍을 피해 (E)\'무쌍돌격\'의 돌진을 사용하세요.', lv6: '6레벨 이후에는 (R)\'현월수호\'를 사용해 문도박사의 공격으로부터 피해를 받지 않는 상태를 활용하세요. 문도가 (R)\'최대 투여량\'으로 체력을 회복할 때는 (R)\'현월수호\'로 밀어내며 킬각을 잡거나 거리를 벌려야 해요. 문도가 궁극기를 사용한 직후에는 무리하게 싸우지 말고 라인을 관리하며 정글러를 부르세요.', item: '헤르메스의 발걸음을 먼저 가서 문도박사의 마법 피해를 견디고 강인함을 챙기세요. 첫 코어 아이템은 갈라진 하늘을 선택해 전투에서 안정적으로 체력을 회복하며 싸우는 것이 좋아요.', spell: '점멸과 점화를 추천해요. 문도박사가 (R)\'최대 투여량\'으로 체력을 크게 회복할 때 점화로 회복 효과를 감소시켜야 해요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'을 조준하여 긴 사거리에서 견제하며 압박해요. (Q)\'삼조격\'을 활용해 빠르게 접근할 준비를 하며, 화살을 조준하느라 바루스가 둔화되는 순간을 이용해 거리를 좁히세요. 너무 멀리서 견제만 받으면 나중에 싸우기 힘들어져요.', lv3: '바루스의 (W)\'역병 화살\' 중첩이 쌓인 상태에서 스킬을 맞으면 피해가 크니 주의하세요. (W)\'풍전참뢰\'로 둔화를 걸고 (E)\'무쌍돌격\'으로 파고들어 짧고 강하게 딜교환을 하세요. 바루스가 (E)\'퍼붓는 화살\'로 만든 지면 위에서는 체력 회복이 줄어드니 조심해야 해요.', lv6: '(R)\'부패의 사슬\'에 맞으면 이동이 막혀 바루스의 공격에 노출되니 조심하세요. (R)\'현월수호\'를 쓰면 창의 사정거리 밖에 있는 적의 (Q)\'꿰뚫는 화살\' 같은 공격을 받지 않으므로 이를 활용해 접근하세요. 정글러를 호출해 바루스가 궁극기를 쓰기 전에 몰아붙이는 것이 좋아요.', item: '첫 코어로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 바루스의 기본 공격 피해를 줄이기 위해 판금 장화를 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도를 이용해 바루스의 사거리를 빠르게 뚫고 진입하세요.' },
    '베인': { lv1: '베인은 (Q)\'구르기\'로 거리를 벌리며 (W)\'은화살\'의 세 번째 공격으로 큰 고정 피해를 줘요. 1~2레벨에는 (Q)\'삼조격\'의 세 번째 공격을 맞히기 위해 무작정 들어가기보다 미니언 뒤에서 기회를 보세요. 베인이 평타를 치러 올 때 짧게 딜교환하고 빠르게 빠지세요.', lv3: '(W)\'풍전참뢰\'를 먼저 맞혀 상대를 도전 받은 상태로 만들면 (E)\'무쌍돌격\'의 사거리가 늘어나 접근하기 편해요. 베인의 (E)\'선고\'는 지형에 부딪히면 기절하니 벽 근처에서는 진입을 피하세요. (E)\'선고\'가 빠진 것을 확인한 뒤 (E)\'무쌍돌격\'으로 들어가 (Q)\'삼조격\'으로 공중으로 띄워 빠르게 딜교환을 마치세요.', lv6: '베인이 (R)\'결전의 시간\'을 켜면 (Q)\'구르기\' 사용 시 투명해지므로 접근하기 매우 까다로워요. (R)\'현월수호\'를 사용해 원거리 공격 피해를 무시하며 베인에게 붙어 강력한 일격을 날리세요. 투명 상태가 되기 전에 빠르게 진입하거나, 투명 지속 시간이 끝나는 타이밍에 맞춰 정글러와 함께 공격하세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 베인의 기본 공격 피해를 줄여주고 갈라진 하늘은 체력과 공격력을 동시에 높여줘요.', spell: '점멸과 점화를 추천해요. 베인이 (Q)\'구르기\'로 도망가기 전에 점화로 지속 피해를 입혀 마무리하세요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'로 이동 속도를 높여 달려들며 기절을 걸기에 조심해야 해요. (W)\'풍전참뢰\'로 먼저 둔화를 걸어 거리를 조절하며 짧게 (Q)\'삼조격\'으로 딜교환하세요.', lv3: '볼리베어가 (W)\'광란의 상처\' 표식을 남기고 다시 사용하여 체력을 회복하지 못하도록 주의하세요. (Q)\'번개 강타\'가 빠진 타이밍에 (E)\'무쌍돌격\'으로 진입하고 (Q)\'삼조격\'의 세 번째 공격으로 공중으로 띄우면 좋아요.', lv6: '볼리베어가 (R)\'폭풍을 부르는 자\'로 포탑을 비활성화하며 들어올 수 있으니 체력이 낮을 때는 조심하세요. 볼리베어는 근접이라 붙어 있으면 (R)\'현월수호\'로도 피해를 받으니 밀쳐낸 뒤 거리를 두고 라인을 관리하세요.', item: '첫 코어로 전투 지속력을 높여주는 갈라진 하늘을 선택하세요. 신발은 볼리베어의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 볼리베어의 (W)\'광란의 상처\'로 인한 체력 회복을 점화로 억제하세요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 회복하며 견제해요. (Q)\'수혈\'은 대상을 직접 지정하니 미니언 뒤에 숨어도 피할 수 없어요. 초반에는 무리하게 맞붙기보다 거리를 조절하며 체력을 보존하세요.', lv3: '(E)\'무쌍돌격\'으로 진입할 때 블라디미르의 (W)\'피의 웅덩이\' 사용을 유도하세요. 웅덩이가 끝나는 타이밍에 (W)\'풍전참뢰\'를 맞춰 둔화를 걸고 (Q)\'삼조격\'으로 연계해요. (E)\'선혈의 파도\'의 피해를 조심하며 적절한 거리에서 싸우세요.', lv6: '(R)\'혈사병\'에 감염되면 받는 피해가 늘어나니 궁극기를 맞았다면 즉시 빠지세요. (R)\'현월수호\'의 피해를 받지 않는 상태를 활용해 킬각을 잡거나 생존하세요. 블라디미르가 성장을 위해 라인을 밀면 정글러를 불러 대응하세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 헤르메스의 발걸음은 마법 저항력을 제공하며, 갈라진 하늘은 전투를 지속하는 데 도움을 줘요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'수혈\'의 체력 회복 효과를 감소시켜야 해요.' },
    '뽀삐': { lv1: '뽀삐 (Q)\'망치 강타\'의 둔화 지대를 피하면서 (Q)\'삼조격\' 세 번째 타격으로 띄우는 딜교환을 하세요. 뽀삐가 (P)\'강철의 외교관\' 방패를 주워 보호막을 얻기 전에 빠르게 평타 교환을 끝내고 빠지세요. 벽 근처에 있으면 (E)\'용감한 돌진\'에 밀려 기절할 수 있으니 라인 중앙을 유지하세요.', lv3: '(E)\'무쌍돌격\'을 쓰기 전 뽀삐의 (W)\'굳건한 태세\'가 켜져 있는지 확인하고, 돌진이 막히지 않게 스킬이 빠진 뒤에 진입하세요. 먼저 (W)\'풍전참뢰\'를 맞춰 도전 상태로 만든 뒤 (E)\'무쌍돌격\'의 늘어난 사거리를 이용해 빠르게 접근하세요. 뽀삐가 (E)\'용감한 돌진\'으로 밀어낼 때 벽에 부딪히지 않도록 항상 퇴로를 확보하세요.', lv6: '(R)\'현월수호\'를 사용해 뽀삐를 밀어내고 거리를 확보한 뒤 (Q)\'삼조격\'으로 역습하세요. 뽀삐의 (R)\'수호자의 심판\' 충전 모션이 보이면 즉시 범위 밖으로 벗어나 멀리 날아가는 상황을 피하세요. 뽀삐가 (E)\'용감한 돌진\'으로 밀어붙일 수 있으니 아군 정글러 위치를 확인하며 라인을 관리하세요.', item: '갈라진 하늘과 판금 장화를 추천해요. 갈라진 하늘은 체력과 공격력을 제공하며 전투 중 유지력을 높여주고, 판금 장화는 뽀삐의 기본 공격 피해를 줄여줘요.', spell: '점멸과 정화를 추천해요. (E)\'용감한 돌진\'으로 벽에 부딪혀 발생한 기절 효과를 정화로 빠르게 풀 수 있어요.' },
    '사이온': { lv1: '(E)\'학살자의 포효\'는 미니언을 맞히면 미니언이 밀려나며 뒤의 적까지 맞히니 미니언 뒤에 숨지 마세요. (Q)\'대량 학살 강타\' 충전 동작이 보이면 범위 밖으로 비켜서서 기절을 피하세요. 스킬이 빗나간 빈틈에 (Q)\'삼조격\'으로 빠르게 공격하고 빠지세요.', lv3: '(W)\'풍전참뢰\'로 상대를 둔화시키고 도전 상태로 만든 뒤, 사거리가 늘어난 (E)\'무쌍돌격\'으로 진입하세요. (W)\'영혼의 용광로\' 보호막이 남아 있을 때 사이온이 다시 사용하면 폭발해 주변에 피해를 주니, 보호막이 켜지면 잠시 거리를 벌렸다가 (Q)\'삼조격\'을 넣으세요. (E)\'학살자의 포효\'에 맞으면 방어력이 깎여 더 큰 피해를 입으니 충격파 방향을 피하세요.', lv6: '(R)\'멈출 수 없는 맹공\'은 저지 불가 상태로 돌진해 적을 띄우니, 일직선상에서 벗어나 옆으로 피하세요. 사이온을 처치해도 (P)\'영광스러운 죽음\'으로 되살아나 공격하니 완전히 사라질 때까지 주의하세요. (R)\'현월수호\'를 사용해 주변 적을 밀어내고 원거리 공격을 막으며 정글러의 합류를 기다리세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 체력이 많은 사이온에게 더 큰 피해를 입히고 생명력 흡수로 버티세요. 신발은 (Q)\'대량 학살 강타\'의 기절 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 사이온은 라인을 빠르게 밀어내므로 순간이동으로 복귀해 경험치 손실을 줄이는 것이 중요해요.' },
    '사일러스': { lv1: '사일러스가 스킬을 사용하여 (P)\'페트리사이트 폭발\'을 충전하면 공격 속도가 빨라지니 평타 교환을 주의하세요. (Q)\'사슬 후려치기\'의 사슬이 교차하는 지점을 피하며 (Q)\'삼조격\'의 세 번째 공격으로 맞받아쳐 체력을 관리해요.', lv3: '사일러스가 (E)\'도주 / 억압\'의 첫 번째 사용으로 돌진해오면 (E)\'무쌍돌격\'으로 대응하세요. (W)\'국왕시해자\'로 들어오며 체력을 회복하려 할 때 (Q)\'삼조격\'의 공중으로 띄우는 효과를 맞춰 딜교환을 끊어주세요. 사일러스의 (E)\'도주 / 억압\' 사슬을 맞기 전에 먼저 진입하는 것이 좋아요.', lv6: '사일러스가 (R)\'강탈\'로 내 (R)\'현월수호\'를 가져가 쓸 수 있으니 주의하세요. 사일러스는 근접이라 붙은 상태에서는 (R)\'현월수호\'로 피해를 막지 못하니 밀쳐낸 뒤 거리 밖에서 킬각을 보세요. 정글러가 왔을 때 사일러스가 훔친 궁극기를 쓰기 전에 (Q)\'삼조격\'으로 띄우는 것이 중요해요.', item: '갈라진 하늘을 첫 코어로 가고 신발은 헤르메스의 발걸음을 선택하세요. 헤르메스의 발걸음은 마법 저항력을 제공하며 (Q)\'사슬 후려치기\'의 둔화 지속시간을 줄여줘요.', spell: '점멸과 점화를 추천해요. 점화로 사일러스가 (W)\'국왕시해자\'를 사용해 체력을 회복하는 것을 억제하세요.' },
    '세주아니': { lv1: '1~2레벨 구간에는 (Q)\'삼조격\'의 마지막 공격으로 상대를 공중으로 띄우며 압박하세요. 세주아니가 (W)\'혹한의 서릿발\'로 둔화를 걸며 접근할 때는 무리하게 붙지 말고 적당한 거리를 유지하며 피해를 최소화해요.', lv3: '3레벨 이후 (W)\'풍전참뢰\'를 먼저 맞춰 도전 상태로 만든 뒤 (E)\'무쌍돌격\'의 증가한 사거리로 진입해 빠르게 딜교환을 해요. 세주아니가 (E)\'만년 서리\'로 기절시키기 전에 (Q)\'삼조격\'의 공격을 모두 적중시키고 빠르게 빠져나오는 것이 중요해요.', lv6: '6레벨 이후 (R)\'현월수호\'를 사용해 주변 적을 밀쳐내고 원거리 공격에 피해를 받지 않는 상태를 만들어 안정적으로 싸우세요. 세주아니가 (R)\'빙하 감옥\'으로 기절시키려 할 때 거리 조절을 통해 스킬을 피하고 정글러와 함께 킬각을 잡으세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 선택해요. 강인함으로 (E)\'만년 서리\'의 기절 지속 시간을 줄이고 체력과 공격력을 높여 유지력을 확보하세요.', spell: '점멸과 점화. 점멸로 (R)\'빙하 감옥\'을 피하고 점화의 추가 피해로 체력이 많은 상대를 빠르게 제압해요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'으로 이동 속도를 얻어 다가오며 다음 두 번의 공격에 최대 체력 비례 피해를 입히니 주의하세요. (Q)\'삼조격\'의 세 번째 공격으로 공중으로 띄울 수 있지만 초반에는 세트의 (P)\'투기장의 투지\' 회복력이 높으니 짧게 딜교환하고 빠지세요.', lv3: '(E)\'무쌍돌격\'으로 진입해 (W)\'풍전참뢰\'로 둔화를 걸고 (Q)\'삼조격\'의 세 번째 공격까지 맞춰서 딜을 넣으세요. 세트의 (W)\'강펀치\'는 저장된 투지로 보호막을 얻고 고정 피해를 입히니 투지가 가득 찼을 때는 맞붙지 말고 거리를 조절하세요. (E)\'안면 강타\'에 휘말리지 않도록 세트의 양옆에 위치하지 않게 조심하세요.', lv6: '세트가 (R)\'대미 장식\'으로 나를 붙잡아 내리꽂으며 제압할 수 있으니 스킬 사용 타이밍을 잘 잡으세요. (R)\'현월수호\'를 사용하면 창의 범위 밖에 있는 적의 공격에 피해를 받지 않으니 세트의 (W)\'강펀치\'를 피하는 용도로 활용하세요. 세트가 궁극기를 사용한 직후에는 다시 붙기 어려우니 라인을 관리하며 정글러의 개입을 기다리세요.', item: '갈라진 하늘을 첫 코어로 가서 체력과 공격력을 챙기고 첫 타격의 치유 효과로 유지력을 높이세요. 신발은 세트의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 세트는 (P)\'투기장의 투지\'로 잃은 체력에 비례해 체력을 회복하니 점화의 치유 감소 효과가 필요해요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 최대 체력 비례 피해를 주고 스킬을 쓰면 (P)\'기 보호막\'을 얻어요. 1~2레벨에는 쉔의 (Q)\'황혼 강습\' 사거리를 조심하며 (Q)\'삼조격\'의 마지막 타격으로 공중 에어본을 노리세요. 쉔의 보호막이 없을 때 (E)\'무쌍돌격\'을 사용하여 진입하며 (P)\'결심\'으로 체력을 회복하며 버티세요.', lv3: '쉔이 (W)\'의지의 결계\'를 펼치면 (Q)\'삼조격\'의 기본 공격이 차단되니 결계가 끝난 뒤에 딜교환을 하세요. 쉔의 (E)\'그림자 돌진\'에 도발되지 않도록 주의하며 (W)\'풍전참뢰\'를 맞춰 둔화를 걸고 (E)\'무쌍돌격\'으로 진입하세요. 쉔의 (E)\'그림자 돌진\'이 빠진 타이밍에 (Q)\'삼조격\'의 마지막 공격을 맞히면 안정적으로 교환할 수 있어요.', lv6: '쉔이 (R)\'단결된 의지\'로 다른 라인에 합류하면 웨이브를 빠르게 밀어 포탑 압박을 이어가세요. 쉔은 근접이라 붙은 상태에서는 (R)\'현월수호\'로 피해를 막지 못하니, (E)\'그림자 돌진\'이 빠진 뒤 (R)\'현월수호\'로 주변에 피해를 주고 (Q)\'삼조격\'으로 띄우세요. 쉔의 (P)\'기 보호막\'이 빠진 타이밍에 이 연계를 넣으면 킬을 노리기 좋아요.', item: '갈라진 하늘을 가서 전투 지속력을 높이세요. 신발은 쉔의 (E)\'그림자 돌진\' 도발 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 쉔이 (E)\'그림자 돌진\'을 사용한 직후에 점화를 사용하여 킬각을 만드세요.' },
    '쉬바나': { lv1: '1~2레벨에는 (E)\'용암 분출\'의 둔화를 피하며 짧은 거리 조절을 하세요. (Q)\'삼조격\'의 세 번째 공격으로 상대를 공중으로 띄워 일방적인 딜교환을 유도하고 빠르게 빠져나오는 것이 좋아요.', lv3: '(W)\'풍전참뢰\'로 상대를 도전 상태로 만든 뒤 (E)\'무쌍돌격\'의 증가한 사거리를 이용해 빠르게 진입하세요. 쉬바나가 (W)\'지옥불 방패\'를 켜면 보호막이 터져 마법 피해가 들어오기 전에 거리를 벌렸다가 다시 (Q)\'삼조격\'으로 공격하세요.', lv6: '쉬바나의 (R)\'용의 강림\'은 저지 불가 상태로 날아오며 경로의 적을 달아나게 하니 날아오는 경로에서 비켜서세요. 용 형상의 쉬바나는 붙어서 싸우니 (R)\'현월수호\'의 피해 면역에 기대지 말고, 착지한 뒤 (R)\'현월수호\'로 주변에 피해를 주며 (Q)\'삼조격\'으로 띄우세요. 정글러와 함께 협공하면 킬을 노리기 쉬워요.', item: '헤르메스의 발걸음과 갈라진 하늘을 선택하세요. 마법 저항력과 강인함으로 군중 제어 지속시간을 줄이고 체력을 보충해 유지력을 높여요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (W)\'지옥불 방패\'의 회복량을 줄이며 확실하게 마무리하세요.' },
    '스웨인': { lv1: '스웨인이 (Q)\'죽음의 손길\'로 견제하며 (P)\'굶주린 새떼\'로 체력을 회복하려 해요. (Q)\'삼조격\'으로 상대를 공중으로 띄우며 빠르게 체력을 깎고 (P)\'결심\'의 회복으로 버티세요. 스웨인의 최대 체력이 늘어나기 전인 초반에 적극적으로 압박하는 것이 중요해요.', lv3: '(E)\'속박명령\'의 파동이 돌아올 때 속박되니 옆으로 움직여 피하시고, 속박되어도 평타와 스킬은 쓸 수 있어요. (W)\'풍전참뢰\'로 먼저 찔러 도전 상태로 만든 뒤, 늘어난 사거리의 (E)\'무쌍돌격\'으로 진입해 (Q)\'삼조격\'까지 연결하세요. (W)\'제국의 눈\'의 둔화에 걸리면 진입이 어려우니 스킬 사용 시점을 잘 잡으세요.', lv6: '스웨인이 (R)\'악의 승천\'을 켜면 주변에서 체력을 흡수하니 너무 오래 붙어 있지 마세요. (R)\'현월수호\'를 사용해 도전 받지 않은 스웨인을 밀쳐내어 흡수 범위 밖으로 보내고 원거리 공격을 무시하세요. (E)\'속박명령\'으로 끌려가기 전에 빠르게 (Q)\'삼조격\'으로 띄워 딜교환을 마치고 정글러와 함께 노리세요.', item: '갈라진 하늘을 가서 체력과 공격력을 높이고 첫 타격 회복으로 버티세요. 신발은 (E)\'속박명령\'의 속박 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 스웨인의 (R)\'악의 승천\'과 (P)\'굶주린 새떼\'로 인한 체력 회복을 점화로 억제해야 해요.' },
    '스카너': { lv1: '1~2레벨에는 (Q)\'삼조격\'의 세 번째 공격으로 상대를 띄우며 짧게 딜교환하세요. 상대가 (Q)\'부서진 대지/지반 돌출\'로 바위를 던져 둔화를 걸지 못하게 거리를 조절하는 것이 중요해요. 기본 공격 위주로 압박하며 체력을 깎아두세요.', lv3: '(W)\'풍전참뢰\'로 먼저 상대를 둔화시키고 (E)\'무쌍돌격\'으로 빠르게 진입해 (Q)\'삼조격\' 연계를 마무리하세요. 상대가 (E)\'이쉬탈의 격돌\'을 사용해 벽으로 밀어붙이려 할 때 빠르게 반응해 피하는 것이 핵심이에요. (W)\'대지의 수호자\' 보호막이 빠진 타이밍에 공격을 집중하세요.', lv6: '(R)\'현월수호\'를 사용하여 주변 적을 밀어내고 (R)\'꿰뚫기\'에 제압당하기 전에 위치를 잡으세요. 상대가 (R)\'꿰뚫기\'로 제압해 끌고 가려 할 때는 제압 중에 스킬과 정화가 통하지 않으니 아군 정글러의 도움을 기다리세요. 라인을 밀어 넣은 뒤 (R)\'꿰뚫기\'가 빠진 타이밍에 킬각을 잡으세요.', item: '갈라진 하늘과 헤르메스의 발걸음을 추천해요. 체력 회복과 공격력을 동시에 챙기고 강인함으로 (E)\'이쉬탈의 격돌\' 기절과 둔화 시간을 줄여야 해요.', spell: '점멸과 점화를 추천해요. (Q)\'삼조격\' 콤보 이후 확실하게 킬을 따내기 위해 점화의 피해가 필요해요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'를 켜고 라인을 빠르게 밀며 뒤로 독을 남겨요. 독구름을 밟으며 무리하게 쫓지 말고, 신지드가 미니언을 치러 다가올 때 (Q)\'삼조격\'으로 띄워 피해를 입히세요. 거리 조절을 하며 (P)\'결심\'의 체력 회복을 챙기세요.', lv3: '(W)\'초강력 접착제\' 위에 있으면 (E)\'무쌍돌격\' 같은 이동 스킬을 사용할 수 없으니 접착제 밖에서 진입하세요. (W)\'풍전참뢰\'를 적중시켜 상대를 도전 받은 상태로 만들면 (E)\'무쌍돌격\'의 사거리가 늘어나 더 쉽게 붙을 수 있어요. 상대의 (E)\'던져넘기기\'가 빠진 것을 확인한 뒤에 (Q)\'삼조격\'으로 띄우세요.', lv6: '(R)\'광기의 물약\'을 사용한 신지드는 매우 단단하고 빠르니 정면에서 계속 싸우지 마세요. (R)\'현월수호\'를 사용하여 주변 적을 밀쳐내고 창이 닿지 않는 거리의 공격을 무시하며 체력을 깎으세요. 라인을 밀어넣고 정글러와 함께 (E)\'무쌍돌격\'으로 진입해 빠르게 처치하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 챙기고 체력 회복으로 버티세요. 신발은 마법 저항력을 높이고 둔화 지속시간을 줄이는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (Q)\'삼조격\'과 연계해 빠르게 킬각을 잡고 (R)\'광기의 물약\'의 체력 재생력을 억제하세요.' },
    '아이번': { lv1: '(Q)\'삼조격\'을 사용해 빠르게 접근하며 압박하세요. 아이번의 (Q)\'덩굴뿌리\'에 속박되면 딜교환이 힘들어지니 미니언 뒤에 숨어 투사체를 피하며 진입하세요. 1~2레벨에는 무리하게 쫓기보다 체력 관리를 하며 기회를 보세요.', lv3: '(W)\'풍전참뢰\'로 상대를 도전 상태로 만든 뒤 (E)\'무쌍돌격\'의 증가한 사거리로 빠르게 진입하세요. 아이번이 (E)\'보호의 씨앗\'으로 보호막을 씌우면 억지로 딜교환하기보다 잠시 물러났다가 보호막이 터진 뒤 다시 공격하세요. (Q)\'삼조격\'의 세 번째 공격으로 상대를 띄워 딜교환 주도권을 잡으세요.', lv6: '(R)\'현월수호\'를 사용해 아이번을 밀쳐내고 원거리 공격을 차단하며 딜교환하세요. 하지만 소환된 (R)\'데이지!\'의 공격에 공중으로 띄워지면 위험하니 데이지의 위치를 확인하며 싸우세요. 라인을 밀어두고 정글러와 함께 갱킹을 호응하며 아이번을 압박하세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 가세요. 헤르메스의 발걸음은 마법 저항력을 제공하고 속박 지속시간을 줄여줘요. 갈라진 하늘은 체력을 높여 생존력을 올리고 일격으로 딜교환을 도와줘요.', spell: '점멸과 점화를 추천해요. 점멸은 진입과 생존에 쓰고 점화는 보호막이 빠진 뒤 마무리 피해로 킬각을 잡기 좋아요.' },
    '아지르': { lv1: '아지르가 (Q)\'사막의 맹습\'을 사용하여 모래 병사로 견제할 때 거리를 조절하며 피해를 줄여요. 1~2레벨 구간에는 무리하게 들어가기보다 (W)\'풍전참뢰\'를 활용해 적절한 거리에서 둔화를 걸며 대응해요. (Q)\'삼조격\'의 세 번째 공격을 준비하며 기회를 엿보세요.', lv3: '(E)\'무쌍돌격\'으로 접근한 뒤 (W)\'풍전참뢰\'를 맞춰 둔화를 걸고 딜교환을 시작해요. 아지르가 (E)\'신기루\'를 사용하여 보호막을 얻고 도망가지 못하도록 (Q)\'삼조격\'의 공중 띄우기를 노려야 해요. 상대의 (W)\'일어나라!\' 공격 범위를 파악하며 거리를 조절하세요.', lv6: '아지르가 (R)\'황제의 진영\'으로 밀어내려 하면 (R)\'현월수호\'를 사용하여 자신을 보호하며 맞대응해요. (R)\'현월수호\'로 창이 닿는 거리 밖에 있는 적의 공격을 받지 않는 상태를 활용해 아지르를 압박하세요. 정글러의 개입이 있다면 (E)\'무쌍돌격\'으로 진입해 킬을 노려요.', item: '헤르메스의 발걸음과 갈라진 하늘을 선택해요. 아지르의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 사고, 전투력을 높이기 위해 갈라진 하늘을 구매해요.', spell: '점멸과 점화. 아지르를 추격하고 킬을 확정하기 위해 점화가 필요해요.' },
    '아칼리': { lv1: '아칼리는 (Q)\'오연투척검\'으로 둔화를 걸며 견제하고 (P)\'암살자의 표식\' 원을 통해 강화 평타를 노려요. 원 경계 근처에서 무리하게 진입하기보다 거리 조절을 하며 (Q)\'삼조격\'의 세 번째 공격으로 아칼리를 띄워 짧은 교환을 시도하세요. 초반에는 기력이 부족한 아칼리의 타이밍을 노려 압박하는 것이 좋아요.', lv3: '(W)\'황혼의 장막\' 안의 아칼리는 대상으로 지정할 수 없으니 연막이 사라지거나 아칼리가 공격해 모습이 드러날 때까지 기다리세요. (E)\'표창곡예\'로 표식이 남으면 돌진해 오니, 먼저 (W)\'풍전참뢰\'로 둔화를 걸고 (E)\'무쌍돌격\'으로 빠르게 접근해 딜교환을 하세요. 아칼리의 (E)\'표창곡예\'가 빠진 타이밍에 (Q)\'삼조격\'을 끝까지 맞히는 것이 핵심이에요.', lv6: '(R)\'무결처형\'의 두 번째 돌진이 들어오는 순간 (R)\'현월수호\'를 사용해 아칼리를 밀어내고 피해를 받지 않는 상태를 유지하세요. (R)\'현월수호\' 이후 (E)\'무쌍돌격\'으로 다시 붙어 (Q)\'삼조격\' 연계로 마무리 킬각을 잡으세요. 아칼리가 연막으로 숨으면 쫓기보다 라인을 밀어 포탑에 압박을 주는 것이 효율적이에요.', item: '갈라진 하늘을 첫 코어로 가서 체력과 공격력을 챙기고 전투 중 체력을 회복하세요. 신발은 아칼리의 마법 피해를 줄이고 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 강력한 지속 피해를 더해 체력이 낮은 아칼리를 확실하게 마무리하세요.' },
    '아크샨': { lv1: '(Q)\'복수의 부메랑\' 견제를 버티며 미니언 뒤에서 체력을 관리하세요. 2레벨이 되면 (E)\'무쌍돌격\'으로 빠르게 진입해 (Q)\'삼조격\' 세 번째 공격으로 상대를 공중으로 띄워 피해를 입히세요.', lv3: '(W)\'풍전참뢰\'를 맞혀 상대를 둔화시키고 도전 상태로 만드세요. 도전 받은 적에게 사거리가 늘어난 (E)\'무쌍돌격\'으로 진입해 (Q)\'삼조격\'을 연계하며 아크샨이 (E)\'영웅의 비상\'으로 도망치기 전에 빠르게 압박하세요.', lv6: '체력이 낮을 때 (R)\'인과응보\'의 큰 피해를 입지 않도록 거리를 조절하세요. (R)\'현월수호\'를 사용해 창이 닿지 않는 거리의 공격을 무시하며 적을 추격하거나, 공격 전 (R)\'현월수호\'로 상대를 밀쳐내어 진입 각도를 조정하세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 기본 공격 피해를 줄이고 체력과 공격력을 동시에 챙기며 전투 중 체력을 회복하기 위해서예요.', spell: '점멸과 점화예요. 부족한 접근력을 보완하고 확실한 마무리 피해를 입히기 위해 선택하세요.' },
    '아트록스': { lv1: '아트록스는 (Q)\'다르킨의 검\' 끝부분에 맞으면 공중으로 띄워지니 범위를 잘 살펴서 피하세요. (P)\'사신 태세\'가 적용된 평타는 회복 효과가 있으니 무작정 평타 교환을 하기보다 (Q)\'삼조격\'의 마지막 공격을 맞히는 것에 집중하세요. 초반에는 상대의 스킬이 빠진 틈을 타서 짧게 치고 빠지세요.', lv3: '(W)\'지옥사슬\'의 범위 안에 갇히면 중앙으로 끌려가 다시 피해를 입으니 맞은 즉시 빠르게 벗어나세요. (W)\'풍전참뢰\'로 상대를 둔화시키고 도전 상태로 만든 뒤, 증가한 사거리의 (E)\'무쌍돌격\'으로 빠르게 접근해 공격하세요. 아트록스가 (E)\'파멸의 돌진\'으로 거리를 조절하며 (Q)\'다르킨의 검\'을 쓸 때 타이밍을 맞춰 파고드는 것이 중요해요.', lv6: '(R)\'세계의 종결자\'를 사용한 아트록스는 회복량과 공격력이 크게 늘어나니 정면에서 오래 싸우지 마세요. (R)\'현월수호\'를 사용해 주변 적을 밀쳐내고 거리 밖의 공격을 무시하며 상대의 궁극기 지속시간이 끝나길 기다리세요. 정글러가 왔을 때 (E)\'무쌍돌격\'으로 빠르게 진입해 상대의 회복 수단을 억제하며 킬각을 잡으세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 피해량을 높이고 생명력 흡수로 버티세요. 신발은 아트록스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과가 (E)\'파멸의 돌진\'과 (R)\'세계의 종결자\'의 강력한 회복력을 억제해 마무리하기 편해요.' },
    '암베사': { lv1: '1~2레벨에는 암베사가 (P)\'용사냥개의 발걸음\'으로 스킬 사용 후 돌진하며 강화된 평타를 치는 타이밍을 조심하세요. (Q)\'교활한 휩쓸기\'의 범위를 피해 거리 조절을 하며 (W)\'풍전참뢰\'를 먼저 적중시켜 둔화를 거는 것이 좋아요. (Q)\'삼조격\'을 활용해 적의 접근을 제어하며 미니언을 챙기세요.', lv3: '암베사가 (W)\'배척\'을 사용해 보호막을 얻으며 준비할 때는 억지로 피해를 주지 말고 기다리세요. (E)\'찢어 가르기\'의 둔화에 걸리지 않도록 (E)\'무쌍돌격\'으로 빠르게 진입하거나 (W)\'풍전참뢰\'로 먼저 둔화를 걸고 거리를 조절하세요. (Q)\'삼조격\'의 세 번째 공격으로 암베사를 공중으로 띄워 스킬 연계를 끊어주는 것이 중요해요.', lv6: '암베사의 (R)\'공개 처형\'은 제압 후 기절을 시키니 체력이 낮을 때는 멀리 떨어져서 대응하세요. 제압에 걸리면 어떤 스킬도 쓸 수 없으니 주의해야 해요. (R)\'현월수호\'를 사용해 암베사의 공격 범위 밖으로 벗어나 피해를 받지 않는 상태를 유지하며 정글러의 개입을 요청하세요.', item: '판금 장화로 암베사의 물리 피해를 줄이고 갈라진 하늘을 첫 코어로 가서 전투 지속력을 높이세요. 적의 강력한 물리 공격을 견디며 교전을 이어가기에 적합해요.', spell: '점멸과 점화를 추천해요. (R)\'공개 처형\' 이후의 기절이 끝나는 타이밍에 점화로 암베사의 체력 회복을 억제하며 마무리하세요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'로 멀리서 견제하며 적을 냉각 상태로 만들어요. 구체가 날아오는 타이밍에 맞춰 옆으로 움직이며 피해를 피하고, (Q)\'삼조격\'을 준비하며 거리를 조절하세요. 초반에는 무리하게 진입하기보다 애니비아의 스킬이 빠진 타이밍을 노려야 해요.', lv3: '애니비아가 (Q)\'냉기 폭발\'로 냉각을 걸면 (E)\'동상\'의 피해가 두 배로 늘어나니 주의하세요. (E)\'무쌍돌격\'으로 진입할 때 애니비아의 (E)\'동상\'을 피하며 붙는 것이 중요해요. (W)\'풍전참뢰\'를 적중시켜 둔화시킨 뒤 (Q)\'삼조격\'의 세 번째 공격으로 공중으로 띄우며 딜교환을 하세요.', lv6: '애니비아가 (W)\'결정화\' 벽으로 길을 막거나 (R)\'얼음 폭풍\'으로 둔화를 걸면 무리하게 뚫지 말고 벽이 녹을 때까지 기다리세요. 진입할 때 (R)\'현월수호\'를 켜 두면 창 거리 밖에 있는 애니비아의 공격 피해를 받지 않으니 이때 거리를 좁히세요. 애니비아는 (P)\'환생\'으로 알이 되어 다시 살아나니, 알이 된 뒤에도 (Q)\'삼조격\'으로 빠르게 깨뜨리세요.', item: '첫 코어로 갈라진 하늘을 가서 전투 지속력을 높이세요. 신발은 애니비아의 마법 피해와 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. (Q)\'냉기 폭발\'의 기절을 정화로 빠르게 풀고 거리를 좁힐 수 있어요.' },
    '야스오': { lv1: '야스오는 (Q)\'강철 폭풍\'을 사용해 견제하며 (P)\'낭인의 길\' 보호막으로 피해를 흡수해요. 첫 교환에서는 (Q)\'삼조격\'으로 야스오의 보호막을 먼저 제거하며 싸우세요. 야스오의 (Q)\'강철 폭풍\' 중첩이 쌓여 회오리바람이 날아올 때는 거리를 조절하며 피해를 피하세요.', lv3: '야스오의 (W)\'바람 장막\'은 투사체만 막으니 (E)\'무쌍돌격\' 같은 돌진은 막지 못해요. (E)\'무쌍돌격\'으로 진입하기 전에 (W)\'풍전참뢰\'를 먼저 맞춰 야스오를 둔화시키고 도전 받은 상태로 만들어 사거리를 늘리세요. 야스오가 (E)\'질풍검\'으로 미니언을 타고 도망치려 할 때 (E)\'무쌍돌격\'을 적중시키는 것이 중요해요.', lv6: '야스오가 (Q)\'강철 폭풍\' 회오리바람으로 나를 띄우면 (R)\'최후의 숨결\'로 이어지니, 회오리바람이 준비된 상태에서는 야스오와 일직선에 서지 마세요. (Q)\'삼조격\'의 마지막 공격으로 야스오를 띄우면 공중에 떠 있는 동안 야스오는 스킬을 쓸 수 없으니 이때 (R)\'현월수호\'까지 이어 피해를 몰아넣으세요. 야스오가 (E)\'질풍검\'으로 미니언을 타고 빠지면 무리하게 쫓지 말고 다음 교전을 준비하세요.', item: '첫 코어로 갈라진 하늘을 선택해 체력과 공격력을 챙기며 전투를 이어나가세요. 신발은 야스오의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 야스오의 (P)\'낭인의 길\' 보호막이 깨진 순간 점화로 마무리 피해를 입히면 킬을 가져오기 쉬워요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 사거리가 늘어난 공격을 하며 방어력을 낮추니 초반에 너무 길게 붙어 있지 마세요. (W)\'풍전참뢰\'를 활용해 적절한 거리를 유지하며 오공의 (P)\'바위 피부\' 효과가 쌓이기 전에 짧은 딜교환을 시도하세요.', lv3: '오공이 (W)\'분신 전사\'로 투명해지며 분신을 남기면 진짜 본체를 찾는 것이 중요해요. 오공이 (E)\'근두운 급습\'으로 들어올 때 (E)\'무쌍돌격\'을 사용하여 빠르게 접근하고 (Q)\'삼조격\'의 세 번째 공격으로 공중으로 띄우세요.', lv6: '오공의 (R)\'회전격\'에 맞으면 공중에 떠 스킬을 쓸 수 없으니 오공이 궁극기를 켜면 범위 밖으로 물러나세요. (R)\'회전격\'이 빠진 뒤 (E)\'무쌍돌격\'으로 붙어 (Q)\'삼조격\'으로 띄우고 (R)\'현월수호\'로 피해를 더하세요. (W)\'분신 전사\'로 남긴 분신에 스킬을 낭비하지 않도록 본체 위치를 확인하는 것이 중요해요.', item: '갈라진 하늘과 판금 장화. 갈라진 하늘로 전투 지속력을 높이고 판금 장화로 오공의 기본 공격 피해를 줄여요.', spell: '점멸과 점화. 점화로 오공의 (P)\'바위 피부\'를 통한 체력 재생을 억제하며 킬각을 잡으세요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'를 던지고 다시 사용해 경로상의 적에게 피해를 주며 견제해요. (Q)\'이중 저주\'가 되돌아오는 경로를 피해 옆으로 이동하며 거리를 조절하세요. (Q)\'삼조격\'을 활용해 미니언을 빠르게 정리하며 라인을 관리하세요.', lv3: '오로라가 (E)\'마법의 문\'을 사용하도록 유도한 뒤 (E)\'무쌍돌격\'으로 거리를 좁히며 추격하세요. 오로라가 (W)\'장막 너머로\'를 써서 투명 상태가 되면 무리하게 쫓지 말고 위치를 파악하며 기다리세요. (W)\'풍전참뢰\'로 먼저 둔화를 걸어 오로라의 움직임을 제어하는 것이 좋아요.', lv6: '오로라가 (R)\'세계의 경계\'를 사용하여 영역을 만들면 그 안에서 교전이 길어질 수 있으니 주의하세요. 오로라의 궁극기 영역 안에서 싸우다 위험해지면 (R)\'현월수호\'를 사용해 범위 밖의 공격으로부터 피해를 받지 않는 상태를 만드세요. (Q)\'삼조격\'의 세 번째 공격으로 적을 띄운 뒤 강력한 피해를 입히며 킬각을 잡으세요.', item: '첫 코어 아이템으로 갈라진 하늘을 가서 전투 지속력을 높이세요. 신발은 오로라의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 오로라는 (P)\'영혼 방호술\'로 체력을 회복하며 버티니 점화로 회복 효과를 줄여주세요.' },
    '오른': { lv1: '오른이 (Q)\'용암 균열\'로 땅을 내리쳐 둔화를 걸며 견제하니 기둥이 생기는 위치를 잘 피하세요. 1~2레벨에는 (Q)\'삼조격\'의 세 번째 공격을 맞히기 위해 짧게 딜교환을 하고 빠지며 체력을 관리해요. 오른이 (Q)\'용암 균열\'을 사용한 직후에는 거리를 좁혀서 평타로 압박하세요.', lv3: '오른의 (E)\'화염 돌진\'이 지형지물에 부딪히면 공중으로 띄우니 벽 근처에서는 주의하세요. (W)\'불꽃 풀무질\'의 마지막 불꽃에 맞으면 불안정 상태가 되어 밀려날 수 있으니 주의하며 (E)\'무쌍돌격\'으로 빠르게 접근하세요. 오른의 (E)\'화염 돌진\'이 빠진 시점에 (Q)\'삼조격\'을 사용하여 적극적으로 딜교환을 시도하세요.', lv6: '오른의 (R)\'대장장이 신의 부름\'이 올 때 정령의 진행 방향 앞에 서 있으면 띄워질 수 있으니 조심하세요. (R)\'현월수호\'로 일정 거리 밖에서 적의 공격을 피하며 킬각을 만드세요. 오른이 (P)\'간이 대장간\'으로 아이템을 업그레이드하기 전에 라인을 강하게 밀어 정글러를 부르는 것이 좋아요.', item: '첫 코어 아이템으로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 오른의 (W)\'불꽃 풀무질\'과 (R)\'대장장이 신의 부름\' 같은 마법 피해와 둔화를 줄이기 위해 헤르메스의 발걸음을 신어주세요.', spell: '점멸과 점화를 추천해요. 오른은 방어력이 높으니 점화로 부족한 피해를 보충하고 킬각을 잡으세요.' },
    '올라프': { lv1: '올라프가 (Q)\'역류\'로 도끼를 던져 방어력을 깎고 이동 속도를 낮추면 거리를 유지하세요. 도끼를 맞았다면 (Q)\'삼조격\'으로 짧게 딜교한 뒤 올라프가 도끼를 주우러 가는 동안 뒤로 빠져야 해요. (P)\'광전사의 분노\' 때문에 올라프의 체력이 낮아질수록 공격 속도가 빨라지니 조심하세요.', lv3: '(E)\'무쌍돌격\'으로 진입할 때 올라프의 (W)\'버티기\' 보호막이 있는지 확인하고 스킬을 쓰세요. (W)\'풍전참뢰\'로 둔화를 걸어 딜교환을 시도하되 올라프가 (E)\'무모한 강타\'를 사용하면 고정 피해를 입으니 주의해야 해요. (Q)\'삼조격\'의 세 번째 공격을 맞히기 위해 거리를 조절하며 공격하세요.', lv6: '올라프가 (R)\'라그나로크\'를 사용하면 이동 방해 효과에 면역이 되니 이 동안은 (Q)\'삼조격\'으로 띄우는 것을 노리지 말고 거리를 벌리세요. (R)\'현월수호\'는 (R)\'라그나로크\'가 켜지기 전에 써서 도전 받지 않은 적을 밀어내고 창 거리 밖의 공격을 피하는 용도로 쓰세요. 올라프의 체력이 낮을 때는 (P)\'광전사의 분노\'로 전투가 길어지니 주의하세요.', item: '판금 장화로 올라프의 기본 공격 피해를 줄이며 버티세요. 첫 코어 아이템으로 갈라진 하늘을 선택해 체력과 공격력을 챙기며 전투 효율을 높이세요.', spell: '점멸과 점화를 추천해요. 점화로 올라프의 (P)\'광전사의 분노\'에 의한 체력 회복 효과를 억제하며 마무리하세요.' },
    '요네': { lv1: '요네가 (Q)\'필멸의 검\' 스택을 쌓아 돌풍으로 띄우려 할 때 거리를 조절하며 대응하세요. (P)\'사냥꾼의 길\' 때문에 평타마다 마법 피해가 섞이니 무리한 평타 교환은 피하는 게 좋아요. (Q)\'삼조격\'을 활용해 초반 웨이브 이후 짧게 딜교하며 체력을 관리하세요.', lv3: '요네의 (W)\'영혼 가르기\' 보호막이 켜진 동안에는 (E)\'무쌍돌격\'으로 진입하지 말고 보호막이 빠지길 기다리세요. 요네가 (E)\'영혼해방\'을 사용해 영혼 상태로 멀리 나갔을 때는 육신이 있는 위치 근처에서 대기하며 복귀 타이밍을 노리세요. (W)\'풍전참뢰\'로 둔화를 걸고 (Q)\'삼조격\'을 맞춰 공중으로 띄우며 딜교환을 시작하세요.', lv6: '요네의 (R)\'운명봉인\'에 맞으면 끌려가며 공중에 떠 스킬을 쓸 수 없으니 요네와 일직선에 서지 마세요. (E)\'영혼해방\'이 끝나고 육신이 돌아오는 순간 (Q)\'삼조격\'의 에어본과 (R)\'현월수호\'를 연계하면 킬을 내기 쉬워요. 요네의 궁극기가 빠진 뒤에는 적극적으로 라인을 밀며 정글러의 도움을 받아 압박하세요.', item: '코어 아이템으로는 갈라진 하늘을 가서 체력과 공격력을 챙기며 전투 지속력을 높이세요. 신발은 요네의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 요네의 (W)\'영혼 가르기\' 보호막이 사라진 뒤에 점화로 마무리 피해를 더하세요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 무덤을 생성하며 체력을 회복하니 미니언 근처에서 무리하게 붙지 마세요. (Q)\'삼조격\'을 사용해 추가 피해를 입히고 재사용 대기시간을 감소시키며 요릭의 (P)\'영혼의 길잡이\' 망령이 생성되기 전에 압박하세요.', lv3: '요릭이 (E)\'애도의 안개\'로 표식을 남기면 안개 망령이 쫓아오니 구체의 방향을 보고 피해야 해요. (E)\'무쌍돌격\'으로 진입할 때는 요릭의 (W)\'망자의 진\' 벽에 갇히지 않도록 주의하며 (W)\'풍전참뢰\'로 둔화를 묻혀주세요.', lv6: '요릭이 (R)\'군도의 장송곡\'으로 안개 마녀를 소환하면 마녀와 함께 싸우는 것은 매우 위험해요. (R)\'현월수호\'를 사용해 도전 받지 않은 적을 밀쳐내고 창의 사거리 밖에서 적의 공격을 피하며 전투를 이어가세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 요릭의 기본 공격 피해를 줄여 주며 갈라진 하늘은 라이트실드 타격으로 첫 공격 때 체력을 회복해요.', spell: '점멸과 점화를 추천해요. 요릭의 (Q)\'최후의 의식\'을 통한 체력 회복을 점화로 억제해야 해요.' },
    '우디르': { lv1: '우디르가 (Q)\'야생 발톱\' 태세로 평타 피해를 늘리며 다가오면 맞대결을 피하세요. (E)\'불길 쇄도\' 태세로 다가와 첫 평타를 맞으면 기절하니 (W)\'풍전참뢰\'를 사용해 거리 조절을 하며 견제하세요. 1~2레벨에는 무리하게 진입하기보다 미니언을 챙기며 우디르의 움직임을 확인하세요.', lv3: '우디르가 (W)\'강철 갑옷\'을 사용해 보호막과 회복을 얻었다면 딜교환을 잠시 멈추세요. (E)\'불길 쇄도\'의 기절은 우디르가 각성하지 않아도 첫 평타에 발동하니 (Q)\'삼조격\'을 활용해 대응하세요. 우디르의 보호막이 빠진 뒤 (E)\'무쌍돌격\'으로 진입해 (Q)\'삼조격\'의 마지막 공격으로 상대를 띄우세요.', lv6: '우디르가 (R)\'날개 돋친 폭풍\'을 사용해 둔화를 걸면 폭풍 밖으로 빠르게 벗어나세요. 우디르가 (E)\'불길 쇄도\'를 재사용해 이동 불가 효과에 면역이 되는 동안에는 (Q)\'삼조격\'의 띄우기나 밀어내기를 노리지 말고 스킬을 아끼세요. (R)\'현월수호\'는 면역이 끝난 뒤나 우디르가 붙기 전에 써서 피해를 받지 않는 상태를 유지하고 정글러의 개입을 요청하세요.', item: '갈라진 하늘을 첫 코어로 선택해 전투 지속력을 높이세요. 신발은 우디르의 (E)\'불길 쇄도\' 기절과 (R)\'날개 돋친 폭풍\' 둔화를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 우디르가 (W)\'강철 갑옷\'으로 체력을 회복할 때 점화를 사용하여 회복 효과를 줄이세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 둔화를 걸며 견제하고 (P)\'화염의 메아리\'로 평타 피해를 입혀요. 폭약의 낙하지점을 피해 이동하며 (Q)\'삼조격\'의 세 번째 공격으로 상대를 공중으로 띄우는 짧은 딜교환을 하세요. 무리하게 붙기보다 (P)\'결심\'의 체력 회복을 활용하며 버티는 것이 좋아요.', lv3: '(W)\'풍전참뢰\'로 먼저 상대를 둔화시키고 도전 상태로 만든 뒤, (E)\'무쌍돌격\'의 증가한 사거리로 빠르게 진입하세요. 우르곳이 (E)\'경멸\'로 나를 뒤로 던지려 할 때 옆으로 피해 스킬을 낭비하게 만드는 것이 중요해요. (W)\'심판의 원\'이 켜진 동안은 정면에서 오래 싸우지 말고 (Q)\'삼조격\'을 빠르게 맞히고 빠지세요.', lv6: '(R)\'불사의 공포\' 섬광탄에 맞은 상태에서 체력이 처형선 아래로 내려가면 제압당해 끌려가니, 그 전에 거리를 벌리거나 싸움을 끝내세요. 우르곳이 (E)\'경멸\'로 나를 던진 직후에 진입해 (Q)\'삼조격\'과 (R)\'현월수호\'로 딜교환을 시작하면 킬각을 잡기 편해요. 섬광탄이 빠진 타이밍에 정글러와 함께 노리는 것도 좋아요.', item: '갈라진 하늘을 첫 코어로 선택해 강력한 한 방 피해와 체력 회복으로 유지력을 높이세요. 신발은 우르곳의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우르곳의 높은 체력을 깎아 (R)\'불사의 공포\' 처형선에 닿기 전에 빠르게 처치하기 위해서예요.' },
    '워윅': { lv1: '워윅은 (Q)\'야수의 송곳니\'로 도약하며 최대 체력 비례 피해를 입히고 체력을 회복하니 1~2레벨에는 무리한 맞딜을 피하며 거리를 조절하세요. 신 짜오의 (Q)\'삼조격\'을 활용해 평타와 함께 피해를 입히며 워윅의 체력이 낮아져 (P)\'끝없는 허기\'로 회복량이 늘어나기 전에 전투를 마무리하는 것이 좋아요.', lv3: '워윅의 (E)\'원시의 포효\'가 켜지면 받는 피해가 줄고 나중에 공포가 걸리니 스킬이 빠진 것을 확인하고 (E)\'무쌍돌격\'으로 진입하세요. (Q)\'삼조격\'의 마지막 공격으로 워윅을 공중에 띄워 흐름을 끊고, (E)\'무쌍돌격\'으로 얻은 공격 속도로 빠르게 몰아치세요. 내 체력이 절반 아래로 내려가면 (W)\'피의 사냥\'으로 워윅의 공격 속도가 빨라지니 체력을 보며 딜교환을 하세요.', lv6: '워윅의 (R)\'무한의 구속\'은 제압이라 걸리면 정화나 스킬로 풀 수 없으니, 체력이 낮을 때 상대 정글러와 함께 노리는 각을 조심하세요. 워윅이 (Q)\'야수의 송곳니\'로 붙으면 (R)\'현월수호\'로 주변에 피해를 주고 (Q)\'삼조격\'으로 띄워 반격하세요. 라인을 당겨서 관리하며 상대의 (R)\'무한의 구속\' 사용을 유도하거나 아군과 함께 싸우세요.', item: '워윅의 마법 피해와 군중 제어 효과에 대비해 헤르메스의 발걸음을 먼저 구매하세요. 첫 코어 아이템은 전투 지속력을 높여주는 갈라진 하늘을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 (Q)\'야수의 송곳니\'와 (P)\'끝없는 허기\'를 통한 체력 회복을 억제하여 킬각을 잡으세요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 들어오며 체력을 회복하고 공격 속도를 쌓으니 주의하세요. (Q)\'삼조격\'의 마지막 공격으로 상대를 띄우고 빠르게 빠져서 (P)\'아이오니아의 열정\' 중첩이 쌓이는 것을 막으세요. 미니언 체력이 낮은 곳에 서 있으면 (Q)\'칼날 쇄도\'의 대상이 되기 쉬우니 거리를 조절하세요.', lv3: '(E)\'쌍검협무\'의 추가 칼날이 날아오는 길목을 피해 기절과 표식을 허용하지 마세요. (W)\'풍전참뢰\'로 적을 둔화시킨 뒤 (E)\'무쌍돌격\'의 증가한 사거리로 진입해 빠르게 공격하세요. 이렐리아가 (W)\'저항의 춤\'을 충전하는 동안에는 물리 피해가 감소하므로 충전이 끝난 뒤에 스킬을 사용하세요.', lv6: '(R)\'선봉진격검\'의 결계 안에서는 둔화되고 표식이 남으니 결계 밖으로 빠르게 벗어나세요. (R)\'현월수호\'를 사용해 도전 받지 않은 이렐리아를 밀쳐내고 거리 밖에서 오는 공격을 무시하며 딜교환을 하세요. 라인 관리 중에 (Q)\'칼날 쇄도\'로 진입하는 타이밍을 보고 (Q)\'삼조격\'으로 공중으로 띄워 정글러의 개입을 기다리세요.', item: '갈라진 하늘을 코어로 선택해 체력과 공격력을 챙기고 전투 중 체력 회복으로 버티세요. 신발은 (P)\'아이오니아의 열정\' 기반의 평타 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'칼날 쇄도\'의 체력 회복 효과를 줄여서 킬각을 잡기 편해요.' },
    '일라오이': { lv1: '일라오이는 (P)\'고대신의 예언자\'로 벽 근처에 촉수를 소환해 공격하니 최대한 지형에서 멀리 떨어져서 싸우세요. 1~2레벨에는 (Q)\'삼조격\'으로 짧게 공격하고 빠르게 빠져나오며 일라오이가 (Q)\'촉수 강타\'를 헛치게 유도하세요. 촉수가 없는 탁 트인 공간에서 짧은 딜교환을 이어가는 것이 좋아요.', lv3: '(E)\'영혼의 시험\'에 맞으면 내 영혼이 분리되고 일라오이가 그 영혼을 때리면 피해 일부가 나에게 들어오며, 영혼에서 멀어지면 내가 숙주가 되어 촉수가 생기니 주의하세요. (W)\'풍전참뢰\'로 먼저 상대를 둔화시킨 뒤 (E)\'무쌍돌격\'으로 빠르게 진입했다가 (W)\'혹독한 가르침\'이 나오기 전에 빠져나오세요. (E)\'영혼의 시험\'이 빠진 뒤에 공격을 시작하는 것이 중요해요.', lv6: '일라오이가 (R)\'믿음의 도약\'을 사용해 주변에 촉수를 많이 소환하면 즉시 범위를 벗어나서 싸움을 피하세요. (R)\'현월수호\'를 사용해 도전 받지 않은 일라오이를 뒤로 밀어내고, 창 거리 밖의 공격을 무시하며 천천히 기회를 보세요. 일라오이가 촉수를 많이 소환했을 때는 정글러와 함께 들어와서 빠르게 처리하는 것이 좋아요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 챙기고 전투 지속력을 높이세요. 신발은 일라오이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 마무리 피해를 더해 촉수에 둘러싸이기 전에 킬각을 잡으세요.' },
    '자크': { lv1: '1~2레벨에는 자크가 (Q)\'탄성 주먹\'으로 적을 붙잡아 둔화시키려 할 때 거리를 조절하며 (Q)\'삼조격\'으로 딜교환을 시도하세요. 자크가 스킬을 맞춰 (P)\'세포 분열\' 조각을 생성하면 조각을 흡수하기 전에 압박하여 회복을 방해해야 해요. 미니언과 겹쳐 서면 (Q)\'탄성 주먹\'에 맞았을 때 다른 적과 충돌할 수 있으니 주의하세요.', lv3: '자크가 (E)\'새총 발사\'나 (Q)\'탄성 주먹\'을 먼저 사용하도록 유도한 뒤 (E)\'무쌍돌격\'으로 빠르게 접근하며 (W)\'풍전참뢰\'를 맞춰 둔화시키세요. 자크가 스킬을 사용한 직후 (Q)\'삼조격\'의 마지막 공격을 사용하여 딜교환을 시도하세요.', lv6: '자크가 (R)\'바운스!\'를 사용하며 튀어 오를 때 (R)\'현월수호\'를 사용해 적을 밀어내고 외부 공격으로부터 자신을 보호하세요. 자크가 (P)\'세포 분열\' 조각을 흡수하며 버티려 하면 (Q)\'삼조격\'으로 적을 띄워 킬각을 잡으세요. 자크의 궁극기에 맞아 공중에 뜨면 스킬을 쓸 수 없으니 주의하며 정글러와 함께 라인을 압박하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 챙기며 전투 지속력을 높이세요. 신발은 자크의 마법 피해를 줄이고 군중 제어 지속시간을 감소시켜주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 자크의 (P)\'세포 분열\'을 통한 체력 회복 효과를 줄여 킬을 내기 쉽게 만드세요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 두 번 공격하며 체력을 회복하니 1~2레벨에는 무리하게 맞딜하지 마세요. 자헨의 (Q)\'다르킨의 글레이브\'가 빠진 것을 확인한 뒤에 (Q)\'삼조격\'을 활용해 짧게 교환하고 빠르게 빠져야 해요.', lv3: '자헨이 (W)\'공포의 귀환\'을 사용하여 내질러 적을 끌어당길 때 직선 방향에서 벗어나서 피해야 해요. 자헨이 (E)\'찬란한 쇄도\'로 돌진해 주변을 가를 때 가장자리 마법 피해를 입지 않도록 (E)\'무쌍돌격\'으로 거리를 조절하며 대응하세요.', lv6: '자헨의 (R)\'단호한 판결\'은 날아올랐다가 내려찍으며 체력을 회복하니, 궁극기가 빠진 뒤에 (E)\'무쌍돌격\'과 (Q)\'삼조격\'으로 진입하고 (R)\'현월수호\'로 피해를 더하세요. 결심이 가득 찬 자헨은 (P)\'전쟁 단련\'으로 부활할 수 있으니 킬각을 볼 때는 부활한 뒤까지 싸울 체력과 스킬을 남겨 두세요. 정글러의 도움을 받아 라인을 압박하는 것이 좋아요.', item: '판금 장화와 갈라진 하늘을 가세요. 판금 장화는 기본 공격으로 받는 피해량을 줄여주고 갈라진 하늘은 전투 지속력을 높여줘요.', spell: '점멸과 점화를 추천해요. 점화는 자헨의 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'을 통한 체력 회복을 억제해요.' },
    '잭스': { lv1: '잭스가 (Q)\'도약 공격\'으로 붙기 전에 (W)\'풍전참뢰\'를 사용해 둔화를 걸고 거리를 조절하세요. (P)\'가차없는 맹공\'으로 잭스의 공격 속도가 올라가면 평타 교환이 힘들어지니 짧게 때리고 빠지세요. 1~2레벨에는 무리하게 붙기보다 (Q)\'삼조격\' 세 번째 타격으로 띄우는 타이밍을 신중하게 잡으세요.', lv3: '잭스가 (E)\'반격\'을 켜면 기본 공격을 모두 피하므로 (Q)\'삼조격\'을 써도 상대를 띄울 수 없으니 스킬이 끝날 때까지 기다리세요. (E)\'반격\' 이후의 기절이 끝나면 (E)\'무쌍돌격\'으로 빠르게 접근해 공격 속도를 얻고 몰아치세요. (W)\'무기 강화\'의 강력한 한 방을 맞지 않도록 잭스의 공격 동작을 잘 살피며 움직이세요.', lv6: '잭스가 (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높였을 때는 정면 대결을 피하세요. 잭스가 (Q)\'도약 공격\'으로 진입해 (E)\'반격\'을 켜면 평타가 막히니, (E)\'반격\'의 기절이 끝난 뒤 (R)\'현월수호\'와 (Q)\'삼조격\'으로 역습하세요. 잭스의 (E)\'반격\'이 빠진 타이밍에 정글러를 불러 함께 압박하세요.', item: '갈라진 하늘을 첫 코어로 가서 체력을 보충하고 첫 타격 체력 회복으로 유지력을 높이세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 탑 라인은 라인 복귀가 중요하니 순간이동으로 손해를 메우고, 점멸은 (E)\'반격\'이 끝난 직후 붙거나 빠질 때 쓰세요.' },
    '제이스': { lv1: '제이스의 캐논 형태 (Q)\'전격 폭발\'은 폭발로 맞은 적 모두에게 피해를 주니 미니언 뒤에 서도 피하기 어려워요. 견제가 강한 구간이니 무리하게 맞붙기보다 미니언을 챙기며 체력을 관리하세요. 제이스가 형태를 바꾸는 틈에 (Q)\'삼조격\'으로 딜교환을 시도하세요.', lv3: '제이스가 해머 형태의 (E)\'천둥 강타\'로 밀쳐내려 할 때 (E)\'무쌍돌격\'을 사용하여 거리를 좁히세요. (W)\'풍전참뢰\'를 적중시켜 제이스를 둔화시키면 도망가기 어려워져요. 제이스의 (E)\'가속 관문\'을 통한 포킹을 조심하며 스킬이 모인 시점에 진입하세요.', lv6: '제이스가 (R)\'머큐리 캐논\'으로 멀리서 공격하며 압박할 때 (R)\'현월수호\'를 사용하여 원거리 공격으로부터 피해를 입지 않는 상태를 유지하세요. 제이스가 해머로 변환하여 (E)\'천둥 강타\'를 쓰기 전에 (E)\'무쌍돌격\'으로 빠르게 붙어야 해요. 제이스가 형태를 바꾸는 타이밍에 맞춰 (Q)\'삼조격\'으로 에어본을 넣으면 킬각을 잡기 쉬워요.', item: '첫 코어로 전투 지속력을 높여주는 갈라진 하늘을 선택하세요. 신발은 제이스의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 제이스가 스킬을 쏟아붓고 형태를 바꾸는 틈을 노려 점화로 압박하세요.' },
    '초가스': { lv1: '초가스가 (Q)\'파열\'로 지면을 파열시켜 공중으로 띄우는 것을 조심하며 바닥의 원을 보고 미리 피하세요. 초가스가 (P)\'육식\'으로 미니언을 먹으며 체력을 회복하지 못하도록 (Q)\'삼조격\'으로 압박하며 라인을 관리해요. (E)\'날카로운 가시\'의 둔화 효과를 조심하며 적절한 거리에서 (W)\'풍전참뢰\'로 견제하세요.', lv3: '초가스가 (W)\'흉포한 울부짖음\'을 사용해 침묵을 걸려고 하면 원뿔 범위를 피해 옆으로 이동하세요. (E)\'무쌍돌격\'으로 진입할 때 초가스가 (Q)\'파열\'을 먼저 쓰지 못하도록 타이밍을 잡고 (W)\'풍전참뢰\'를 맞춰 둔화를 거세요. (Q)\'삼조격\'의 마지막 공격으로 초가스를 공중으로 띄우면 효과적으로 딜교환을 할 수 있어요.', lv6: '초가스의 (R)\'포식\'은 큰 고정 피해를 주니 체력이 낮은 상태에서는 거리를 유지하며 조심하세요. (R)\'현월수호\'를 사용하여 도전받지 않은 적을 뒤로 밀쳐내고 창의 범위 밖에서 들어오는 공격을 피하며 싸우세요. 초가스가 (R)\'포식\'으로 성장하기 전에 정글러와 함께 압박하여 킬을 노리는 것이 좋아요.', item: '첫 코어로 갈라진 하늘을 구매해 전투 지속력을 높이세요. 신발은 초가스의 마법 피해를 줄이고 침묵 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 초가스의 (P)\'육식\'을 통한 체력 회복 효과를 감소시키세요.' },
    '카밀': { lv1: '카밀은 (P)\'적응형 방어 체계\'로 보호막을 얻고 (Q)\'정확성 프로토콜\'로 추가 피해를 입히며 압박해요. (Q)\'삼조격\'을 활용해 초반에 맞대응하며 (P)\'결심\'의 회복 효과를 챙기는 것이 중요해요. 카밀이 (Q)\'정확성 프로토콜\'을 재사용하기 전에 거리를 조절하며 웨이브를 관리하세요.', lv3: '카밀의 (W)\'전술적 휩쓸기\' 바깥쪽 절반에 맞으면 둔화와 추가 피해를 받고 카밀이 체력을 회복하니, 카밀에게 붙거나 옆으로 피해야 해요. (E)\'갈고리 발사\'로 벽을 타고 들어와 기절을 시키려 할 때 (E)\'무쌍돌격\'으로 대응하세요. (W)\'풍전참뢰\'로 카밀을 둔화시킨 뒤 (Q)\'삼조격\'의 마지막 타격으로 공중에 띄우며 딜교환을 하세요.', lv6: '카밀이 (R)\'마법공학 최후통첩\'으로 가두면 어떤 방법으로도 탈출할 수 없으니 영역 안에서 맞서 싸울 준비를 하세요. 영역 안에서는 카밀이 가까이 붙어 있어 (R)\'현월수호\'의 피해 면역이 통하지 않으니, (R)\'현월수호\'로 피해를 주고 (Q)\'삼조격\'으로 띄워 반격하세요. 카밀의 (E)\'갈고리 발사\'를 조심하며 정글러를 불러 함께 싸우면 좋아요.', item: '첫 코어로 갈라진 하늘을 가서 전투 지속력을 높이세요. 신발은 카밀의 기본 공격 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 카밀의 (W)\'전술적 휩쓸기\'를 통한 체력 회복을 억제하세요.' },
    '카사딘': { lv1: '(Q)\'삼조격\'을 활용해 초반 웨이브를 밀어내며 짧게 딜교환을 시도하세요. 카사딘의 (Q)\'무의 구체\' 보호막은 마법 피해만 흡수하니 신 짜오의 평타와 (Q)\'삼조격\'의 물리 피해는 그대로 들어가요. 카사딘이 약한 초반에 거리를 좁혀 압박을 이어가세요.', lv3: '(W)\'풍전참뢰\'를 적중시켜 둔화를 걸고 (E)\'무쌍돌격\'으로 빠르게 진입하세요. 카사딘이 (E)\'힘의 파동\'을 사용하기 전에 (Q)\'삼조격\'의 세 번째 공격을 맞혀서 흐름을 가져와야 해요. 상대의 스킬 재사용 대기시간을 확인하며 싸우는 것이 중요해요.', lv6: '카사딘이 (R)\'균열 이동\'으로 들어오면 (Q)\'삼조격\'으로 띄워 연속 사용을 끊어 주세요. 카사딘이 빠져나가 창 거리 밖에서 스킬을 쓸 때 (R)\'현월수호\'를 켜 두면 그 피해를 받지 않아요. 라인을 밀어넣고 정글러를 호출해 압박을 지속하세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 선택해요. 헤르메스의 발걸음으로 마법 저항력과 강인함을 챙기고, 갈라진 하늘로 체력과 공격력을 보충해요.', spell: '점멸과 점화를 사용해요. 점화로 부족한 피해를 보충하고 순간적으로 적을 압박하여 킬을 노려요.' },
    '카시오페아': { lv1: '카시오페아가 (Q)\'맹독 폭발\'로 견제할 때 거리를 조절하며 미니언을 챙기세요. 1~2레벨에는 무리한 진입보다는 (Q)\'삼조격\'의 세 번째 공격을 활용해 체력을 관리하며 버티는 것이 좋아요.', lv3: '(E)\'무쌍돌격\'으로 진입하기 전 카시오페아가 (W)\'독기의 늪\'을 사용하도록 유도하여 스킬을 빼는 것이 좋아요. (W)\'풍전참뢰\'를 맞혀 둔화를 걸고 빠르게 (Q)\'삼조격\'으로 딜교환을 마무리하세요.', lv6: '카시오페아의 (R)\'석화의 응시\'는 자신을 바라보는 적을 기절시키니 등을 돌려 둔화로 바꾸거나 범위 밖으로 피하세요. 궁극기가 빠지면 (E)\'무쌍돌격\'으로 붙고 (R)\'현월수호\'로 피해를 더해 킬을 노리세요. 정글러의 개입을 유도할 때는 도전 받은 적에게 (E)\'무쌍돌격\' 사거리가 늘어나는 점을 활용해 빠르게 접근하세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 마법 저항력을 얻고 (Q)\'삼조격\'을 포함한 공격력을 높이기 위해서예요.', spell: '점멸과 점화를 추천해요. (R)\'석화의 응시\'를 피하며 진입하기 위해 점멸이 필요하고, 카시오페아가 (E)\'쌍독니\'로 회복하는 것을 막기 위해 점화를 사용해요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'을 던져 (P)\'폭풍의 표식\'을 남기며 견제하니 투사체가 날아올 때 옆으로 움직여서 피해를 줄이세요. 표식이 쌓이면 기절할 수 있으니 거리를 조절하며 (Q)\'삼조격\'을 활용해 짧게 딜교환을 시도하세요. 초반에는 무리하게 진입하기보다 미니언을 챙기며 기회를 엿보세요.', lv3: '케넨이 (E)\'번개 질주\'로 들어오며 표식을 쌓을 때는 (W)\'풍전참뢰\'를 맞춰 둔화시키며 거리를 조절하세요. (E)\'무쌍돌격\'으로 돌진한 뒤 (Q)\'삼조격\'의 마지막 공격으로 상대를 공중으로 띄워 (P)\'폭풍의 표식\' 스택이 쌓이는 것을 끊어내세요. 케넨의 (W)\'전류 방출\'이 빠진 타이밍을 노려 진입하는 것이 좋아요.', lv6: '케넨의 (R)\'날카로운 소용돌이\'는 주변 적에게 계속 마법 피해를 주니 케넨이 궁극기를 켜면 범위에서 빠르게 벗어나세요. 궁극기가 빠진 뒤 (E)\'무쌍돌격\'으로 붙어 (R)\'현월수호\'로 피해를 주고 (Q)\'삼조격\'으로 띄워 킬각을 잡으세요. 케넨이 궁극기를 사용한 직후에 정글러를 호출하여 압박하면 좋아요.', item: '첫 코어로 갈라진 하늘을 가서 전투 지속력을 높이세요. 신발은 케넨의 마법 피해와 기절 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점멸로 케넨의 표식이 쌓이기 전에 진입이나 이탈을 하고, 점화로 체력이 낮은 케넨을 마무리하세요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'으로 성장할수록 강해지니 1~2레벨 구간이 가장 약한 구간이에요. 케일이 (Q)\'광휘의 일격\'으로 견제할 때 거리를 조절하며 (Q)\'삼조격\'을 활용해 적극적으로 압박하세요. 첫 웨이브를 빠르게 밀어넣고 케일이 미니언을 먹을 때 (E)\'무쌍돌격\'으로 진입해 딜교환을 하세요.', lv3: '케일이 (E)\'화염주문검\'을 사용하여 잃은 체력 비례 피해를 입히려고 하면 무리하게 싸우지 마세요. (W)\'풍전참뢰\'를 맞춰 케일을 둔화시킨 뒤 (E)\'무쌍돌격\'으로 빠르게 접근하는 것이 좋아요. 케일의 (W)\'천상의 축복\'으로 체력을 회복하기 전에 (Q)\'삼조격\'의 세 번째 공격으로 공중으로 띄워 흐름을 끊으세요.', lv6: '케일이 (R)\'신성한 심판\'으로 자신을 무적으로 만들면 킬을 따기 어려우니 궁극기 유무를 꼭 확인하세요. 케일의 궁극기가 빠진 것을 확인했다면 (R)\'현월수호\'로 적을 밀어내며 피해를 받지 않는 상태를 유지해 전투를 이끄세요. 정글러를 부를 때 케일이 (E)\'화염주문검\'으로 반격할 수 있으니 미리 거리를 좁혀두는 것이 좋아요.', item: '헤르메스의 발걸음을 가서 케일의 마법 피해와 군중 제어 효과에 대비하세요. 첫 코어 아이템으로는 전투 지속력을 높여주는 갈라진 하늘을 추천해요.', spell: '점멸과 점화를 추천해요. 케일이 성장하기 전에 점화로 체력 회복 효과를 감소시키며 압박하세요.' },
    '코그모': { lv1: '1~2레벨에는 코그모의 (Q)\'부식성 침\'과 (W)\'생체마법 폭격\'의 긴 사거리에 주의하며 적절한 거리를 유지해요. 무리하게 다가가기보다는 미니언을 정리하며 (Q)\'삼조격\'의 재사용 대기시간이 돌아오기를 차분히 기다려요.', lv3: '(W)\'풍전참뢰\'를 적중시켜 도전 상태를 먼저 만들면 (E)\'무쌍돌격\'의 사거리가 길어져 접근하기 편해요. 코그모가 (W)\'생체마법 폭격\'을 켠 동안에는 평타가 강해지니, 효과가 끝난 뒤 (Q)\'삼조격\'으로 진입하여 공중에 띄워요.', lv6: '(R)\'현월수호\'의 효과를 활용해 코그모의 (R)\'살아있는 곡사포\' 공격으로부터 피해를 받지 않는 상태를 유지하며 진입해요. 코그모의 (E)\'공허의 분비물\' 둔화를 조심하면서 정글러와 함께 적극적으로 압박해요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 코그모의 마법 피해를 줄이고 전투 지속력을 높여야 해요.', spell: '점멸과 점화. (Q)\'삼조격\'의 공중 에어본 이후 점화로 부족한 피해를 보충해요.' },
    '코르키': { lv1: '코르키의 (Q)\'인광탄\'이 떨어지는 위치를 확인하며 피해를 최소화하고 미니언 근처에서 버텨요. 1~2레벨 구간에서는 상대의 사거리가 길기 때문에 무리하게 진입하기보다는 (Q)\'삼조격\'을 아껴두며 체력을 보존하는 것이 좋아요.', lv3: '(W)\'풍전참뢰\'로 상대를 둔화시킨 뒤 (E)\'무쌍돌격\'을 사용하여 빠르게 접근하세요. 코르키가 (E)\'개틀링 건\'을 사용해 방어력을 낮추기 전에 (Q)\'삼조격\'의 세 번째 타격을 맞춰 상대를 공중으로 띄우는 것이 중요해요.', lv6: '(R)\'현월수호\'를 사용하여 코르키의 (R)\'미사일 폭격\' 피해를 입지 않는 상태로 전투를 시작해요. 코르키가 (W)\'발키리\'를 사용해 도망가려 할 때 (E)\'무쌍돌격\'으로 빠르게 따라붙으며 라인은 당겨서 관리해요.', item: '헤르메스의 발걸음과 갈라진 하늘을 가요. 코르키의 마법 피해에 대응하기 위해 헤르메스의 발걸음을 사고 체력과 공격력을 모두 챙기기 위해 갈라진 하늘을 올려요.', spell: '점멸과 점화. 코르키의 낮은 체력을 빠르게 깎아 킬을 내기 위해 점화를 선택해요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식과 (Q)\'실명 공격\'으로 원거리 견제가 강해요. (Q)\'실명 공격\'은 처음 적중한 적에게만 시야 감소를 걸지만 그 주변의 모든 적에게 피해를 주니 미니언과 붙어 서지 마세요. 퀸이 무리하게 진입하면 (Q)\'삼조격\'의 세 번째 공격으로 띄워 피해를 입히세요.', lv3: '퀸이 (E)\'공중제비\'로 밀어내며 거리를 벌리기 전에 (W)\'풍전참뢰\'를 적중시켜 둔화를 거세요. 도전 상태가 된 퀸에게는 (E)\'무쌍돌격\' 사거리가 증가하니 이를 이용해 끝까지 추격해 붙으세요. 퀸이 (W)\'예리한 감각\'으로 이동 속도를 높여 도망가더라도 (Q)\'삼조격\'으로 빠르게 공격해 체력을 깎으세요.', lv6: '퀸이 (R)\'후방 지원\'으로 빠르게 날아와 강습하면 (R)\'현월수호\'를 사용해 창이 닿지 않는 거리의 공격 피해를 피하세요. 원거리 퀸을 밀쳐내면 오히려 거리가 벌어지니 밀어내기에 의존하지 말고 퀸이 붙은 뒤 (Q)\'삼조격\'으로 역습하세요. 퀸이 로밍을 위해 자리를 비우면 빠르게 라인을 밀어 포탑 피해를 누적시키세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력을 보충하고 첫 타격으로 피해를 입히세요. 신발은 퀸의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (E)\'공중제비\' 이후 빈틈이 생겼을 때 점화로 확실하게 처치하세요.' },
    '크산테': { lv1: '크산테가 (Q)\'엔토포 타격\'으로 둔화를 걸고 두 번 적중시켜 기절시키려 할 때 거리를 벌리세요. (Q)\'삼조격\'의 세 번째 공격으로 상대를 띄우며 짧게 딜교환하고 빠르게 빠져나오는 것이 좋아요. 첫 웨이브부터 무리하게 붙기보다 상대의 스킬 사용 여부를 확인하며 체력을 관리하세요.', lv3: '크산테가 (W)\'길을 여는 자\'를 충전하며 저지 불가 상태가 될 때는 (E)\'무쌍돌격\'이나 (W)\'풍전참뢰\'를 사용하지 말고 옆으로 피하세요. (W)\'풍전참뢰\'로 먼저 둔화를 걸고 늘어난 거리의 (E)\'무쌍돌격\'으로 진입해 (Q)\'삼조격\'을 빠르게 맞히는 구도를 만드세요. (E)\'발놀림\'으로 보호막을 얻으며 들어오는 타이밍에 맞춰 공격을 시작하세요.', lv6: '크산테가 (R)\'총공세\'를 사용하면 자신의 최대 체력과 추가 방어력이 줄어드는 대신 피해량과 흡혈이 늘어나니 정면 평타 싸움을 길게 하지 마세요. (R)\'총공세\' 상태에서는 (W)\'길을 여는 자\'가 적을 밀어내거나 기절시키지 않으니 이때 (Q)\'삼조격\'과 (R)\'현월수호\'로 강하게 압박하세요. 벽 근처에서는 (R)\'총공세\'에 맞아 벽 너머로 밀려날 수 있으니 라인 관리를 통해 중앙에서 싸우세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 챙기고 타격 시 체력 회복으로 유지력을 높이세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 순간이동을 추천해요. 크산테는 체력이 많아 빠르게 처치하기 어려우니 순간이동으로 운영하며 손해를 줄이세요.' },
    '클레드': { lv1: '클레드는 (Q)\'덫날리기\'로 적을 붙잡아 끌어당기며 1~2레벨 구간에서 강한 모습을 보여요. 덫에 맞은 채 클레드 근처에 머물면 끌려가니 맞자마자 거리를 벌리세요. 클레드가 덫을 빗맞혔다면 (Q)\'삼조격\'을 사용하여 빠르게 적을 공중으로 띄워주세요.', lv3: '(W)\'버럭버럭\'으로 공격 속도가 빨라진 클레드와는 길게 평타 싸움을 하지 마세요. 클레드가 (E)\'이랴!\'로 돌진할 때 (W)\'풍전참뢰\'를 적중시켜 둔화와 도전 상태를 만드세요. 클레드가 스칼에서 내린 상태라면 (E)\'무쌍돌격\'으로 빠르게 접근해 몰아붙이세요.', lv6: '(R)\'돌겨어어억!!!\'을 사용해 보호막을 얻고 돌진하는 클레드는 매우 위협적이니 라인을 당겨 받으세요. 클레드가 진입할 때 (R)\'현월수호\'를 사용하여 주변 적을 밀쳐내고 피해를 받지 않는 상태를 활용하세요. 스칼에서 내린 클레드는 챔피언 피해량이 줄어드니 이때를 노려 킬을 노리세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 보충하고 교전 중 체력을 회복하세요. 신발은 클레드의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 스칼에서 내린 클레드는 챔피언에게 주는 피해가 줄어드니 이때 점화로 마무리 피해를 더해 빠르게 처치하세요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 견제하며 (P)\'절대 미각\' 중첩을 쌓아요. 중첩이 세 번 쌓이면 다음 (Q)\'혀 채찍\'에 기절할 수 있으니 평타 교환을 짧게 하세요. (E)\'무쌍돌격\'으로 진입하여 (Q)\'삼조격\'의 세 번째 공격까지 맞히고 빠지는 것이 좋아요.', lv3: '탐 켄치가 (W)\'심연 잠수\'를 사용하면 범위 안의 적을 공중으로 띄우니 주의하세요. (E)\'두꺼운 피부\'를 사용하면 비축한 피해가 보호막으로 바뀌니 보호막이 사라진 뒤에 딜을 넣으세요. (E)\'무쌍돌격\'으로 접근한 뒤 (Q)\'삼조격\'으로 상대를 공중에 띄우며 딜교환을 하세요.', lv6: '탐 켄치가 (R)\'집어삼키기\'를 쓰기 위해 (P)\'절대 미각\' 중첩을 쌓으려 할 때 조심하세요. (R)\'현월수호\'를 사용하여 주변 적을 밀어내고 공격을 받지 않는 상태를 활용해 교전을 이끄세요. 라인을 빠르게 밀어 넣고 정글러의 개입을 유도하는 것도 좋아요.', item: '첫 코어로 갈라진 하늘을 가서 공격력과 체력을 확보하세요. 신발은 탐 켄치의 마법 피해를 줄이고 강인함을 얻을 수 있는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 체력 회복 효과를 줄이세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 흡수하며 1~2레벨 평타 교환이 강해요. (Q)\'깨물기\'를 맞았다면 무리하게 싸우지 말고 (Q)\'삼조격\'의 마지막 공격인 에어본을 활용해 빠져나오세요. 트런들은 (P)\'헌납\'으로 주변 유닛이 쓰러질 때 회복하니 미니언이 많은 곳에서는 교환을 피하세요.', lv3: '트런들이 (W)\'얼음 왕국\'을 깔면 그 영역 안에서 공격 속도와 이동 속도가 올라가니 영역 밖에서 싸우세요. (E)\'얼음 기둥\'에 걸려 이동 경로가 막히지 않도록 주의하며 (E)\'무쌍돌격\'으로 거리를 좁히세요. 트런들의 (Q)\'깨물기\'가 빠진 시점에 (W)\'풍전참뢰\'를 맞히고 (Q)\'삼조격\'으로 딜교환을 하세요.', lv6: '트런들의 (R)\'진압\'은 체력과 방어력, 마법 저항력을 훔치니 맞았다면 효과가 끝날 때까지 거리를 벌리며 버티세요. (R)\'진압\'이 빠진 뒤 (E)\'얼음 기둥\' 위치를 피해 (E)\'무쌍돌격\'으로 붙고 (R)\'현월수호\'와 (Q)\'삼조격\'으로 몰아치세요. 트런들은 근처에서 적이 쓰러질 때마다 회복하니 미니언이 많은 곳에서 무리하게 킬각을 잡지 마세요.', item: '몰락한 왕의 검을 첫 코어로 가서 전투 지속력을 높이세요. 신발은 트런들의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 트런들의 (P)\'헌납\'과 (W)\'얼음 왕국\'을 통한 회복을 억제하세요.' },
    '트린다미어': { lv1: '트린다미어는 (P)\'격노\'로 분노를 모을수록 치명타 확률이 높아지니 초반에 무리하게 맞붙지 마세요. (Q)\'삼조격\'의 세 번째 공격으로 트린다미어를 공중에 띄워 흐름을 끊고 짧게 교환해요. 첫 웨이브는 미니언을 챙기며 트린다미어가 (Q)\'피의 갈망\'으로 체력을 회복하기 전에 거리를 조절하세요.', lv3: '(W)\'풍전참뢰\'를 먼저 적중시켜 둔화를 걸고 도전 상태를 만든 뒤 (E)\'무쌍돌격\'으로 진입하세요. 트린다미어가 (E)\'회전 베기\'를 사용하며 들어오면 정면에서 비켜나 피해를 줄여야 해요. (Q)\'삼조격\'의 세 번째 타격으로 트린다미어를 띄우면 (Q)\'피의 갈망\'을 쓰기 전에 전투를 압박할 수 있어요.', lv6: '트린다미어가 (R)\'불사의 분노\'를 사용하면 체력이 더 내려가지 않으니 그동안은 무리하게 딜을 넣지 말고 거리를 벌리며 버티세요. (R)\'불사의 분노\' 지속시간이 끝난 직후가 가장 좋은 킬 타이밍이니 이때 (E)\'무쌍돌격\', (Q)\'삼조격\', (R)\'현월수호\'를 쏟아부어 마무리하세요. 라인을 빠르게 밀어 트린다미어가 (Q)\'피의 갈망\'으로 체력을 회복할 여유를 주지 마세요.', item: '첫 코어로 갈라진 하늘을 선택해 전투에서 생존력을 확보하세요. 신발은 트린다미어의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 트린다미어가 (Q)\'피의 갈망\'을 사용해 체력을 회복하는 것을 억제하세요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\' 독이 평타마다 붙어 지속 피해를 줘요. 이 독은 기본 공격에 붙는 효과라 미니언 뒤에 숨어도 막을 수 없으니 평타 교환을 짧게 끊으세요. (W)\'풍전참뢰\'를 맞춰 둔화시킨 뒤 다가갈 기회를 노려보세요.', lv3: '티모의 (Q)\'실명 다트\'에 맞으면 (Q)\'삼조격\'이나 (P)\'결심\' 같은 기본 공격 기반 스킬을 사용하기 어려워요. 실명 상태에서는 무리하게 딜교하지 말고 (W)\'풍전참뢰\'와 (E)\'무쌍돌격\'을 활용해 위치를 조절하세요. 티모의 (Q)\'실명 다트\'가 빠진 뒤에 (E)\'무쌍돌격\'으로 접근하세요.', lv6: '(R)\'유독성 함정\'을 밟으면 둔화와 피해를 입으니 설치된 위치를 주의 깊게 확인하세요. (R)\'현월수호\'는 티모가 창이 닿지 않는 거리에서 평타를 칠 때 피해를 막아 주니 그때 쓰세요. 밀어내기는 거리를 벌려 주니 노리지 말고 (E)\'무쌍돌격\'으로 붙어 (Q)\'삼조격\'으로 압박하세요.', item: '첫 코어로 삼위일체를 선택해 전투력을 높이세요. 신발은 마법 저항력을 얻고 강인함으로 둔화 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 티모가 (W)\'신속한 이동\'을 써서 도망갈 때 점멸로 거리를 좁히고 점화로 마무리하세요.' },
    '판테온': { lv1: '판테온은 1~2레벨 구간에 (Q)\'혜성의 창\'으로 멀리서 견제하며 압박이 강해요. (Q)\'삼조격\'을 이용해 짧게 딜교환을 하고 빠르게 빠져서 체력 손실을 줄이세요. (P)\'필멸자의 의지\'가 충전되어 강화된 스킬이 나가기 전까지는 거리 조절을 하며 신중하게 행동하세요.', lv3: '(E)\'방패 돌격\'이 켜진 동안은 정면 공격에 무적이니 딜을 멈추고 옆으로 움직이세요. (W)\'방호의 도약\' 기절에 걸리면 스킬을 쓸 수 없으므로 상대의 도약이 빠진 뒤에 (E)\'무쌍돌격\'으로 진입하세요. (W)\'풍전참뢰\'로 둔화를 걸어 (Q)\'삼조격\'의 세 번째 공격까지 확실하게 맞히는 것이 중요해요.', lv6: '(R)\'거대 유성\'이 떨어지는 지점에서 빠르게 벗어나야 피해를 줄일 수 있어요. 판테온이 진입했을 때 (R)\'현월수호\'를 사용해 주변 적을 밀쳐내고 피해를 받지 않는 상태로 안전하게 싸우세요. 판테온이 궁극기로 다른 라인에 개입하면 빠르게 라인을 밀어 넣고 정글러를 호출하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 챙기고 전투 유지력을 높이세요. 신발은 판테온의 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 초반 강한 딜교환 후에 점화로 마무리하여 판테온의 압박을 빠르게 끊어내세요.' },
    '피들스틱': { lv1: '1~2레벨 구간에는 피들스틱이 시야 밖에서 (Q)\'공포\'를 사용하여 공격하는 것을 조심하며 라인을 관리하세요. (Q)\'삼조격\'을 활용해 적극적으로 교전하며 상대의 체력을 깎아두는 것이 좋아요. 상대가 숨어서 기습하지 못하도록 와드를 통해 시야를 계속 확보하세요.', lv3: '(E)\'무쌍돌격\'으로 빠르게 접근하여 피들스틱의 (W)\'풍작\' 정신 집중을 (Q)\'삼조격\'의 공중 띄우기로 끊어주세요. (E)\'수확\'의 범위 중심에 맞으면 침묵에 걸릴 수 있으니 주의하며 스킬을 사용하세요. (W)\'풍전참뢰\'로 둔화를 걸며 (P)\'결심\'의 효과를 받아 딜교환을 진행하세요.', lv6: '피들스틱이 (R)\'까마귀 폭풍\'으로 진입하면 (R)\'현월수호\'를 사용해 주변 적을 밀어내고 피해를 받지 않는 상태를 만드세요. (Q)\'삼조격\'을 통해 상대를 띄워 킬을 노려보세요. 상대가 궁극기를 사용한 뒤에는 다시 시야를 확보하며 정글러의 개입에 대비하세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 가요. (Q)\'공포\'나 (E)\'수확\'의 군중 제어 지속시간을 줄이고 전투 효율을 높이기 위해서예요.', spell: '점멸과 점화를 선택하세요. 피들스틱의 (W)\'풍작\'을 통한 체력 회복을 억제하고 확실하게 적을 마무리하기 위해서예요.' },
    '피오라': { lv1: '피오라는 (P)\'치명적인 검무\'로 급소를 찌르면 회복하고 이동 속도가 올라가니 급소 위치를 계속 확인하며 움직이세요. 1~2레벨에는 무리하게 진입하지 말고 (Q)\'삼조격\'의 세 번째 공격으로 띄우는 타이밍을 노려 짧게 교환하세요. 피오라가 (Q)\'찌르기\'로 들어올 때 거리를 조절하며 평타 위주로 압박하세요.', lv3: '피오라의 (W)\'응수\'는 모든 공격과 이동 불가 효과를 막아내고 기절을 거니, (W)\'응수\'가 켜진 동안에는 (Q)\'삼조격\'의 에어본이나 (E)\'무쌍돌격\'을 쓰지 마세요. (W)\'풍전참뢰\'로 먼저 상대를 둔화시켜 도전 상태로 만든 뒤 (E)\'무쌍돌격\'의 증가한 사거리로 빠르게 진입하세요. (E)\'대가의 검술\'의 치명타 공격이 나오기 전에 딜교환을 마치고 빠지는 것이 좋아요.', lv6: '피오라가 (R)\'대결투\'를 사용하면 급소가 네 군데 드러나니 최대한 움직이며 급소를 내주지 마세요. (R)\'현월수호\'를 사용해 도전받지 않은 피오라를 밀쳐내고 거리 밖에 있는 공격으로부터 피해를 받지 않는 상태를 유지하세요. (W)\'응수\'가 빠진 타이밍에 (Q)\'삼조격\'과 (E)\'무쌍돌격\'을 연계해 빠르게 킬각을 잡으세요.', item: '갈라진 하늘을 첫 코어로 가서 체력을 보충하고 첫 타격의 치유 효과로 유지력을 높이세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 피오라의 (P)\'치명적인 검무\'와 (R)\'대결투\'로 인한 체력 회복을 점화의 치유 감소로 억제하세요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 설치해 거리 조절을 하며 공격해요. 포탑 근처에서는 이동 속도가 빨라지니 무작정 들어가지 말고 (Q)\'삼조격\'을 활용해 짧게 딜교환하세요. 첫 웨이브는 포탑의 사거리를 피해 막타 위주로 챙기세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'의 중앙에 맞으면 기절하니 주의하며 움직이세요. (W)\'풍전참뢰\'로 적을 도전 상태로 만든 뒤 (E)\'무쌍돌격\'으로 빠르게 접근해 딜교환하세요. (W)\'마법공학 초소형 로켓\'이 모이는 지점에서 빠르게 벗어나며 공격하세요.', lv6: '(R)\'업그레이드!!!\' 이후 사용하는 강화 스킬은 피해가 매우 크니 주의하세요. (R)\'현월수호\'를 사용해 원거리 공격을 차단하며 하이머딩거 본체에 붙어 공격하세요. 포탑이 없는 빈틈을 노려 정글러와 함께 기습하는 게 좋아요.', item: '맬모셔스의 아귀를 가서 마법 저항력을 높이고 생명선 보호막으로 생존력을 챙기세요. 신발은 기절 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 하이머딩거의 포탑 압박으로 인해 라인 관리가 어려울 수 있으니 순간이동으로 손해를 메우세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_xinzhao);
if (typeof module !== 'undefined') module.exports = top_xinzhao;
